/** All translations for zizhitongjian ch.029 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起上章執徐，盡著雍困敦，凡九年。", literal: "From Shangzhang Zhixu through Zhuyong Kundun; nine years in all.", idiomatic: "From Shangzhang Zhixu through Zhuyong Kundun—nine years in all." },
  { zh: "1春，二月，馮奉世還京師，更為左將軍，賜爵關內侯。", literal: "1. In spring, the second month, Feng Fengshi returned to the capital, was reassigned as Left General, and was granted the rank of Marquis Within the Passes.", idiomatic: "1. In spring, the second month, Feng Fengshi returned to the capital, was reassigned as Left General, and was made Marquis Within the Passes." },
  { zh: "----2三月，立皇子康為濟陽王。", literal: "----2 In the third month, the prince Kang was established as King of Jiyang.", idiomatic: "----2 In the third month, Prince Kang was established as King of Jiyang." },
  { zh: "----3夏，四月，癸未，平昌考侯王接薨。", literal: "----3 In summer, the fourth month, on guiwei, Wang Jie, Marquis Kao of Pingchang, died.", idiomatic: "----3 In summer, the fourth month, on guiwei, Wang Jie, Marquis Kao of Pingchang, died." },
  { zh: "秋，七月，壬戌，以平恩侯許嘉為大司馬、車騎將軍。", literal: "In autumn, the seventh month, on renxu, Ping'en Marquis Xu Jia was appointed Grand Marshal and General of Chariots and Cavalry.", idiomatic: "In autumn, the seventh month, on renxu, Ping'en Marquis Xu Jia was appointed Grand Marshal and General of Chariots and Cavalry." },
  { zh: "----4冬，十一月，己丑，地震，雨水。", literal: "----4 In winter, the eleventh month, on jichou, there was an earthquake and rainwaters.", idiomatic: "----4 In winter, the eleventh month, on jichou, there was an earthquake and heavy rain." },
  { zh: "----5復鹽鐵官；", literal: "----5 The salt and iron offices were restored;", idiomatic: "----5 The salt and iron monopolies were restored;" },
  { zh: "置博士弟子員千人。", literal: "a quota of one thousand Erudite disciples was established.", idiomatic: "a quota of one thousand Erudite disciples was established." },
  { zh: "以用度不足，民多復除，無以給中外繇役故也。", literal: "Because expenditures were insufficient and the people had many exemptions from tax and corvée, there was nothing with which to supply internal and external levies and corvée.", idiomatic: "Because revenues fell short and the people had too many tax and corvée exemptions, there was nothing left to meet court and local levies and labor." },
  { zh: "1春，二月，赦天下。", literal: "1. In spring, the second month, a general amnesty was proclaimed.", idiomatic: "1. In spring, the second month, the empire was pardoned." },
  { zh: "----2三月，上行幸雍，祠五畤。", literal: "----2 In the third month, the emperor traveled in favor to Yong and sacrificed at the Five Altars.", idiomatic: "----2 In the third month, the emperor traveled to Yong and sacrificed at the Five Altars." },
  { zh: "----3夏，六月，甲戌，孝宣園東闕災。", literal: "----3 In summer, the sixth month, on jiaxu, the eastern gate-tower of Emperor Xiaoxuan's park-tomb burned.", idiomatic: "----3 In summer, the sixth month, on jiaxu, the eastern gate-tower of Emperor Xuan's park-tomb burned." },
  { zh: "----4戊寅晦，日有食之。", literal: "----4 On wuyin's last day of the month, there was an eclipse of the sun.", idiomatic: "----4 On the last day of wuyin, there was a solar eclipse." },
  { zh: "上於是召諸前言日變在周堪、張猛者責問，皆稽首謝；", literal: "Thereupon the emperor summoned those who had earlier spoken of solar changes—Zhou Kan and Zhang Meng—to rebuke and question them; all kowtowed and apologized;", idiomatic: "Thereupon the emperor summoned Zhou Kan and Zhang Meng, who had earlier spoken of solar changes, to rebuke and question them; all kowtowed and apologized;" },
  { zh: "因下詔稱堪之美，徵詣行在所，拜為光祿大夫，秩中二千石，領尚書事；", literal: "thereupon an edict praised Kan's excellence, summoned him to the traveling palace, appointed him Household Grandee at rank of two thousand shi, and put him in charge of Secretariat affairs;", idiomatic: "thereupon an edict praised Kan's excellence, summoned him to the traveling palace, appointed him Household Grandee at rank of two thousand shi, and put him in charge of Secretariat affairs;" },
  { zh: "猛復為太中大夫、給事中。", literal: "Meng was restored as Grand Palace Grandee and Palace Writer.", idiomatic: "Meng was restored as Grand Palace Grandee and Palace Writer." },
  { zh: "中書令石顯管尚書，尚書五人皆其黨也；", literal: "Palace Secretariat Director Shi Xian managed the Secretariat; all five Secretaries were his faction;", idiomatic: "Palace Secretariat Director Shi Xian managed the Secretariat; all five Secretaries were his faction;" },
  { zh: "堪希得見，常因顯白事，事決顯口。", literal: "Kan rarely got audience; he usually reported affairs through Xian, and decisions came from Xian's mouth.", idiomatic: "Kan rarely gained audience; he usually reported affairs through Xian, and decisions came from Xian's mouth." },
  { zh: "會堪疾喑，不能言而卒。", literal: "As it happened Kan fell ill with muteness, could not speak, and died.", idiomatic: "As it happened Kan fell ill with muteness, could not speak, and died." },
  { zh: "顯誣譖猛，令自殺於公車。", literal: "Xian slandered Meng and had him kill himself at the public carriage office.", idiomatic: "Xian slandered Meng and had him kill himself at the public carriage office." },
  { zh: "----5初，貢禹奏言：「孝惠、孝景廟皆親盡宜毀，及郡國廟不應古禮，宜正定。", literal: "----5 Initially, Gong Yu memorialized: \"The temples of Emperors Xiaohui and Xiaojing have all reached the limit of mourning kin and should be demolished; the temples in commanderies and kingdoms do not accord with ancient ritual and should be properly set right.", idiomatic: "----5 Initially, Gong Yu memorialized: \"The temples of Emperors Hui and Jing have all reached the limit of mourning kin and should be demolished; the temples in commanderies and kingdoms do not accord with ancient ritual and should be properly set right." },
  { zh: "」天子是其議。", literal: "\" The Son of Heaven approved his proposal.", idiomatic: "\" The emperor approved his proposal." },
  { zh: "秋，七月，戊子，罷昭靈-{后}-、武哀王、昭哀-{后}-、衛思-{后}-、戾太子、戾-{后}-園，皆不奉祠，裁置吏卒守焉。", literal: "In autumn, the seventh month, on wuzi, the park-tombs of Empress Zhaoling, Prince Wuai, Empress Zhaoai, Empress Weisi, the Crown Prince Li, and Empress Li were abolished—all ceased to receive sacrifice, and only just enough clerks and soldiers were stationed to guard them.", idiomatic: "In autumn, the seventh month, on wuzi, the park-tombs of Empress Zhaoling, Prince Wuai, Empress Zhaoai, Empress Weisi, the Crown Prince Li, and Empress Li were abolished—all ceased to receive sacrifice, and only a bare guard of clerks and soldiers was left." },
  { zh: "冬，十月，乙丑，罷祖宗廟在郡國者。", literal: "In winter, the tenth month, on yichou, ancestral temples in commanderies and kingdoms were abolished.", idiomatic: "In winter, the tenth month, on yichou, ancestral temples in commanderies and kingdoms were abolished." },
  { zh: "----6諸陵分屬三輔。", literal: "----6 The various imperial tombs were parcelled out among the Three Metropolises.", idiomatic: "----6 The various imperial tombs were parcelled out among the Three Metropolises." },
  { zh: "以渭城壽陵亭部原上為初陵。", literal: "The plateau above Weicheng's Shouling pavilion district was made the site of the first imperial tomb.", idiomatic: "The plateau above Weicheng's Shouling pavilion district was made the site of the first imperial tomb." },
  { zh: "詔勿置縣邑及徙郡國民。", literal: "An edict ordered that counties and towns not be established and that people of commanderies and kingdoms not be relocated.", idiomatic: "An edict ordered that no counties or towns be established and that people of commanderies and kingdoms not be relocated." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1. In spring, the first month, the emperor traveled in favor to Sweet Springs and sacrificed at the border to the Great Altar.", idiomatic: "1. In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "三月，幸河東，祠-{后土}-。", literal: "In the third month, he favored Hedong and sacrificed to -{后土}- Earth.", idiomatic: "In the third month, he favored Hedong and sacrificed to -{后土}- Earth." },
  { zh: "----2秋，穎川水流殺人民。", literal: "----2 In autumn, the Ying River's waters killed the people.", idiomatic: "----2 In autumn, the Ying River's flood killed the people." },
  { zh: "----3冬，上幸長楊射熊館，大獵。", literal: "----3 In winter, the emperor favored the Bear-Shooting Lodge at Changyang and held a great hunt.", idiomatic: "----3 In winter, the emperor favored the Bear-Shooting Lodge at Changyang and held a great hunt." },
  { zh: "----4十二月，乙酉，毀太上皇、孝惠皇帝寢廟園，用韋玄成等之議也。", literal: "----4 In the twelfth month, on yiyou, the park-tombs and sleeping temples of the Grand Supreme Emperor and Emperor Xiaohui were demolished, following the proposal of Wei Xuancheng and others.", idiomatic: "----4 In the twelfth month, on yiyou, the park-tombs and sleeping temples of the Grand Supreme Emperor and Emperor Hui were demolished, following the proposal of Wei Xuancheng and others." },
  { zh: "----5上好儒術、文辭，頗改宣帝之政。", literal: "----5 The emperor favored Confucian learning and literary polish and considerably altered Emperor Xuan's policies.", idiomatic: "----5 The emperor favored Confucian learning and literary polish and considerably altered Emperor Xuan's policies." },
  { zh: "言事者多進見，人人以為得上意。", literal: "Those who spoke on affairs were many in advancing audience; each thought he had the emperor's intent.", idiomatic: "Many who spoke on affairs gained audience; each thought he had won the emperor's favor." },
  { zh: "又傅昭儀及子濟陽王康愛幸，逾於皇后、太子。", literal: "Moreover Lady Fu Zhao and her son King Kang of Jiyang were favored beyond the empress and crown prince.", idiomatic: "Moreover Lady Fu Zhao and her son King Kang of Jiyang were favored beyond the empress and crown prince." },
  { zh: "太子少傅匡衡上疏曰：「臣聞治亂安危之機，在乎審所用心。", literal: "Crown Prince Junior Tutor Kuang Heng submitted a memorial saying: \"Your servant has heard that the pivot of order and disorder, safety and peril, lies in scrutinizing where the heart is applied.", idiomatic: "Crown Prince Junior Tutor Kuang Heng submitted a memorial saying: \"I have heard that the pivot of order and disorder, safety and peril, lies in scrutinizing where the heart is applied." },
  { zh: "蓋受命之王，務在創業垂統，傳之無窮；", literal: "For a king who receives the Mandate, the task is to found the enterprise and hand down the line, transmitting without end;", idiomatic: "For a king who receives the Mandate, the task is to found the enterprise and hand down the line without end;" },
  { zh: "繼體之君，心存於承宣先王之德而褒大其功。", literal: "A ruler who succeeds the foundation keeps his heart on carrying forward and proclaiming the former king's virtue and magnifying his achievement.", idiomatic: "A ruler who succeeds the foundation keeps his heart on carrying forward and proclaiming the former king's virtue and magnifying his achievement." },
  { zh: "昔者成王之嗣位，思述文、武之道以養其心，休烈盛美皆歸之二-{后}-，而不敢專其名，是以上天歆享，鬼神祐焉。", literal: "Of old when King Cheng succeeded the throne, he sought to set forth the Way of Wen and Wu to nourish his heart; splendid merit and great beauty were all ascribed to the two -{后}- queens, and he dared not monopolize the name—hence Heaven was pleased to enjoy, and ghosts and spirits protected him.", idiomatic: "Of old when King Cheng succeeded the throne, he sought to set forth the Way of Wen and Wu to nourish his heart; splendid merit and great beauty were all ascribed to the two -{后}- queens, and he dared not claim the credit—hence Heaven was pleased and ghosts and spirits protected him." },
  { zh: "陛下聖德天覆，子愛海內，然而陰陽未和，奸邪未禁者，殆議者未丕揚先帝之盛功，爭言制度不可用也，務變更之，所更或不可行而復復之，是以群下更相是非，吏民無所信。", literal: "Your Majesty's sage virtue covers Heaven and cherishes the realm as children, yet yin and yang are not harmonized and treachery is not suppressed—perhaps because debaters have not greatly proclaimed the former emperor's splendid achievements, contend that the institutions cannot be used, and strive to change them; what is changed sometimes cannot be carried out and is changed back again—hence officials below alternate in affirming and denying, and clerks and commoners have nothing to trust.", idiomatic: "Your Majesty's sage virtue covers Heaven and cherishes the realm as children, yet yin and yang are not harmonized and treachery is not suppressed—perhaps because debaters have not greatly proclaimed the former emperor's splendid achievements, contend that the institutions cannot be used, and strive to change them; what is changed sometimes cannot be carried out and is changed back again—hence officials below alternate in affirming and denying, and clerks and commoners have nothing to trust." },
  { zh: "臣竊恨國家釋樂成之業，而虛為此紛紛也！", literal: "Your servant secretly grieves that the state abandons an established accomplishment and makes this turmoil in vain!", idiomatic: "I secretly grieve that the state abandons an established accomplishment and makes this turmoil in vain!" },
  { zh: "願陛下詳覽統業之事，留神於遵制揚功，以定群下之心。", literal: "May Your Majesty carefully review affairs of the inherited enterprise and keep your mind on following institutions and exalting achievement, to settle the hearts of those below.", idiomatic: "May Your Majesty carefully review affairs of the inherited enterprise and keep your mind on following institutions and exalting achievement, to settle the hearts of those below." },
  { zh: "《詩》《大雅》曰：『無念爾祖，聿脩厥德。", literal: "The Book of Songs, Greater Odes, says: \"Do not forget your ancestors—forthwith cultivate their virtue.", idiomatic: "The Book of Songs, Greater Odes, says: \"Do not forget your ancestors—forthwith cultivate their virtue." },
  { zh: "』蓋至德之本也。", literal: "\" That is the root of supreme virtue.", idiomatic: "\" That is the root of supreme virtue." },
  { zh: "《傳》曰：『審好惡，理情性，而王道畢矣。", literal: "The Classicist's tradition says: \"Scrutinize likes and dislikes, regulate emotion and nature, and the kingly Way is complete.", idiomatic: "The Classicist's tradition says: \"Scrutinize likes and dislikes, regulate emotion and nature, and the kingly Way is complete." },
  { zh: "』治性之道，必審己之所有餘而強其所不足，蓋聰明疏通者戒於太察，寡聞少見者戒於壅蔽，勇猛剛強者戒於太暴，仁愛溫良者戒於無斷，湛靜安舒者戒於後時，廣心浩大者戒於遺忘。", literal: "\" The Way of governing nature must scrutinize what one has in surplus and strengthen what one lacks—for the clever and penetrating must guard against over-scrutiny, the narrow-hearing and few-seeing against blockage, the fierce and strong against over-violence, the benevolent and gentle against lack of decision, the deep and calm against lateness, the broad-hearted and vast against forgetfulness.", idiomatic: "\" The Way of governing nature must scrutinize what one has in surplus and strengthen what one lacks—for the clever and penetrating must guard against over-scrutiny, the narrow-hearing and few-seeing against blockage, the fierce and strong against over-violence, the benevolent and gentle against indecision, the deep and calm against lateness, the broad-hearted and vast against forgetfulness." },
  { zh: "必審己之所當戒而齊之以義，然後中和之化應，而巧偽之徒不敢比周而望進。", literal: "One must scrutinize what one should guard against and align it with righteousness; then the transformation of central harmony responds, and clever falsifiers dare not draw together in factions hoping to advance.", idiomatic: "One must scrutinize what one should guard against and align it with righteousness; then the transformation of central harmony responds, and clever falsifiers dare not draw together in factions hoping to advance." },
  { zh: "唯陛下戒之，所以崇聖德也！", literal: "Only Your Majesty—guard against these; thereby exalt sage virtue!", idiomatic: "Only Your Majesty—guard against these; thereby exalt sage virtue!" },
  { zh: "「臣又聞室家之道修，則天下之理得，故《詩》始《國風》，《禮》本冠、婚。", literal: "\" Your servant further hears that when the household Way is cultivated, then the realm's principle is attained—hence the Book of Songs begins with Airs of the States, and the Rites take cap-and-girdle and marriage as foundation.", idiomatic: "\" I further hear that when the household Way is cultivated, the realm's principle is attained—hence the Book of Songs begins with Airs of the States, and the Rites take cap-and-girdle and marriage as foundation." },
  { zh: "始乎《國風》，原情性以明人倫也；", literal: "It begins with Airs of the States to trace emotion and nature and clarify human relations;", idiomatic: "It begins with Airs of the States to trace emotion and nature and clarify human relations;" },
  { zh: "本乎冠、婚，正基兆以防未然也。", literal: "it grounds itself in cap-and-girdle and marriage to correct the foundation and guard against what has not yet happened.", idiomatic: "it grounds itself in cap-and-girdle and marriage to correct the foundation and guard against what has not yet happened." },
  { zh: "故聖王必慎妃-{后}-之際，別適長之位，禮之於內也。", literal: "Therefore the sage king must be careful at the juncture of consort and -{后}- queen, distinguish the position of the legitimate eldest son, and ritualize within the household.", idiomatic: "Therefore the sage king must be careful at the juncture of consort and -{后}- queen, distinguish the position of the legitimate eldest son, and ritualize within the household." },
  { zh: "卑不逾尊，新不先故，所以統人情而理陰氣也；", literal: "The low does not exceed the high, the new does not precede the old—thus to harmonize human sentiment and regulate yin qi;", idiomatic: "The low does not exceed the high, the new does not precede the old—thus to harmonize human sentiment and regulate yin qi;" },
  { zh: "其尊適而卑庶也，適子冠乎阼，禮之用醴，眾子不得與列，所以貴正體而明嫌疑也。", literal: "to honor the legitimate and lower the secondary—the eldest legitimate son caps himself at the eastern stair, the rite uses unfermented wine, other sons may not share in the ranks—thus to value the correct body and clarify what is in doubt.", idiomatic: "to honor the legitimate and lower the secondary—the eldest legitimate son caps himself at the eastern stair, the rite uses unfermented wine, other sons may not share in the ranks—thus to value the correct body and clarify what is in doubt." },
  { zh: "非虛加其禮文而已，乃中心與之殊異，故禮探其情而見之外也。", literal: "It is not merely piling on ritual text—the heart within is fundamentally different from them, so ritual probes the feeling and displays it outward.", idiomatic: "It is not merely piling on ritual text—the heart within is fundamentally different, so ritual probes the feeling and displays it outward." },
  { zh: "聖人動靜游燕所親，物得其序，則海內自修，百姓從化。", literal: "The sage's movements and rest, wandering and feasting, and whom he favors—when each thing attains its order, then within the seas all of themselves cultivate, and the hundred clans follow the transformation.", idiomatic: "The sage's movements and rest, wandering and feasting, and whom he favors—when each thing attains its order, the realm cultivates itself and the people follow the transformation." },
  { zh: "如當親者疏，當尊者卑，則佞巧之奸因時而動，以亂國家。", literal: "If what should be close is kept distant and what should be honored is made low, then crafty flatterers stir according to the moment and disorder the state.", idiomatic: "If what should be close is kept distant and what should be honored is made low, crafty flatterers stir according to the moment and disorder the state." },
  { zh: "故聖人慎防其端，禁於未然，不以私恩害公義。", literal: "Therefore the sage is careful to bar the beginning and forbids what has not yet happened, not letting private favor harm public righteousness.", idiomatic: "Therefore the sage is careful to bar the beginning and forbids what has not yet happened, not letting private favor harm public righteousness." },
  { zh: "《傳》曰：『正家而天下定矣！", literal: "The Classicist's tradition says: \"Correct the household and the realm is settled!", idiomatic: "The Classicist's tradition says: \"Correct the household and the realm is settled!" },
  { zh: "』」----6初，武帝既塞宣房，後河復北決於館陶，分為屯氏河，東北入海，廣深與大河等，故因其自然，不堤塞也。", literal: "\" \" ----6 Initially, after Emperor Wu had dammed Xuanyang, the river later burst north again at Guantao, dividing into the Tunshi River, which flowed northeast into the sea—broad and deep equal to the Great River—so they followed its natural course and did not dike and block it.", idiomatic: "\" \" ----6 Initially, after Emperor Wu had dammed Xuanyang, the river later burst north again at Guantao, dividing into the Tunshi River, which flowed northeast into the sea—broad and deep as the Great River—so they followed its natural course and did not dike and block it." },
  { zh: "是歲，河決於清河靈鳴犢口，而屯氏河絕。", literal: "That year the river burst at Qinghe's Lingmingdu mouth, and the Tunshi River was cut off.", idiomatic: "That year the river burst at Qinghe's Lingmingdu mouth, and the Tunshi River was cut off." },
  { zh: "1春，正月，戊辰，隕石於梁。", literal: "1. In spring, the first month, on wuchen, a meteorite fell in Liang.", idiomatic: "1. In spring, the first month, on wuchen, a meteorite fell in Liang." },
  { zh: "----2三月，上行幸雍，祠五畤。", literal: "----2 In the third month, the emperor traveled in favor to Yong and sacrificed at the Five Altars.", idiomatic: "----2 In the third month, the emperor traveled to Yong and sacrificed at the Five Altars." },
  { zh: "----3冬，河間王元坐賊殺不辜廢，遷房陵。", literal: "----3 In winter, King Yuan of Hejian was deposed for the crime of killing the innocent and was moved to Fangling.", idiomatic: "----3 In winter, King Yuan of Hejian was deposed for killing the innocent and was moved to Fangling." },
  { zh: "----4罷孝文太后寢祠園。", literal: "----4 The sleeping temple and sacrificial park of Empress Dowager Xiaowen was abolished.", idiomatic: "----4 The sleeping temple and sacrificial park of Empress Dowager Wen was abolished." },
  { zh: "----5上幸虎圈鬥獸，後宮皆坐。", literal: "----5 The emperor favored the Tiger Enclosure for beast-fighting; the rear palace all sat by.", idiomatic: "----5 The emperor favored the Tiger Enclosure for beast-fighting; the rear palace all sat by." },
  { zh: "熊逸出圈，攀檻欲上殿，左右、貴人、傅婕妤等皆驚走。", literal: "A bear escaped the enclosure, climbed the railing intending to ascend the hall—the attendants, noble ladies, Lady Fu Jieyu, and others all fled in alarm.", idiomatic: "A bear escaped the enclosure, climbed the railing intending to ascend the hall—the attendants, noble ladies, Lady Fu Jieyu, and others all fled in alarm." },
  { zh: "馮婕妤直前，當熊而立。", literal: "Lady Feng Jieyu went straight forward and stood in the bear's path.", idiomatic: "Lady Feng Jieyu went straight forward and stood in the bear's path." },
  { zh: "左右格殺熊。", literal: "The attendants struck and killed the bear.", idiomatic: "The attendants struck and killed the bear." },
  { zh: "上問：「人情驚懼，何故前當熊？", literal: "The emperor asked: \"Human nature is alarm and fear—why did you advance to block the bear?", idiomatic: "The emperor asked: \"Human nature is alarm and fear—why did you advance to block the bear?" },
  { zh: "」婕妤對曰：「猛獸得人而止，妾恐熊至御坐，故以身當之。", literal: "\" The lady answered: \"Fierce beasts stop when they have a person—I feared the bear would reach the imperial seat, so I used my body to block it.", idiomatic: "\" The lady answered: \"Fierce beasts stop when they have a person—I feared the bear would reach the imperial seat, so I used my body to block it." },
  { zh: "」帝嗟歎，倍敬重焉。", literal: "\" The emperor sighed in admiration and doubly honored her.", idiomatic: "\" The emperor sighed in admiration and doubly honored her." },
  { zh: "傅婕妤慚，由是與馮婕妤有隙。", literal: "Lady Fu Jieyu was ashamed; from this she bore a rift with Lady Feng Jieyu.", idiomatic: "Lady Fu Jieyu was ashamed; from this she bore a rift with Lady Feng Jieyu." },
  { zh: "馮婕妤，左將軍奉世之女也。", literal: "Lady Feng Jieyu was the daughter of Left General Fengshi.", idiomatic: "Lady Feng Jieyu was the daughter of Left General Fengshi." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1. In spring, the first month, the emperor traveled in favor to Sweet Springs and sacrificed at the border to the Great Altar.", idiomatic: "1. In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "三月，行幸河東，祠后土。", literal: "In the third month, he traveled in favor to Hedong and sacrificed to Queen Earth.", idiomatic: "In the third month, he traveled to Hedong and sacrificed to Queen Earth." },
  { zh: "----2夏，四月，赦天下。", literal: "----2 In summer, the fourth month, a general amnesty was proclaimed.", idiomatic: "----2 In summer, the fourth month, the empire was pardoned." },
  { zh: "----3六月，立皇子興為信都王。", literal: "----3 In the sixth month, Prince Xing was established as King of Xindu.", idiomatic: "----3 In the sixth month, Prince Xing was established as King of Xindu." },
  { zh: "----4東郡京房學《易》於梁人焦延壽。", literal: "----4 Jing Fang of Dong commandery studied the Changes under Jiao Yanshou of Liang.", idiomatic: "----4 Jing Fang of Dong commandery studied the Changes under Jiao Yanshou of Liang." },
  { zh: "延壽常曰：「得我道以亡身者，京生也。", literal: "Yanshou often said: \"One who obtains my Way and loses his body—that is Jing.", idiomatic: "Yanshou often said: \"One who obtains my Way and loses his body—that is Jing." },
  { zh: "」其說長於災變，分六十卦，更直日用事，以風雨寒溫為候，各有占驗。", literal: "\" His doctrine excelled in calamities and changes; he divided the sixty hexagrams, rotating duty day by day for affairs, taking wind, rain, cold, and warmth as signs—each had verification.", idiomatic: "\" His doctrine excelled in calamities and changes; he divided the sixty hexagrams, rotating duty day by day for affairs, taking wind, rain, cold, and warmth as signs—each had verification." },
  { zh: "房用之尤精，以孝廉為郎，上疏屢言災異，有驗。", literal: "Fang applied it with especial refinement; as a Filial and Incorrupt recruit he became a gentleman-of-the-palace, memorialized repeatedly on calamities and anomalies, and had verification.", idiomatic: "Fang applied it with especial refinement; as a Filial and Incorrupt recruit he became a gentleman-of-the-palace, memorialized repeatedly on calamities and anomalies, and was proved right." },
  { zh: "天子說之，數召見問。", literal: "The Son of Heaven was pleased and summoned him repeatedly for questioning.", idiomatic: "The emperor was pleased and summoned him repeatedly for questioning." },
  { zh: "房對曰：「古帝王以功舉賢，則萬化成，瑞應著；", literal: "Fang answered: \"Ancient emperors and kings raised the worthy by merit—then the myriad things were transformed and auspicious responses appeared;", idiomatic: "Fang answered: \"Ancient emperors and kings raised the worthy by merit—then the myriad things were transformed and auspicious responses appeared;" },
  { zh: "末世以毀譽取人，故功業廢而致災異。", literal: "in the decadent age men are taken by slander and praise—hence achievements are abandoned and calamities and anomalies arise.", idiomatic: "in the decadent age men are taken by slander and praise—hence achievements are abandoned and calamities and anomalies arise." },
  { zh: "宜令百官各試其功，災異可息。", literal: "It would be fitting to order the hundred officials each to be tested by achievement—calamities and anomalies can cease.", idiomatic: "It would be fitting to order the hundred officials each to be tested by achievement—calamities and anomalies can cease." },
  { zh: "」詔使房作其事，房奏考功課吏法。", literal: "\" An edict had Fang compose this affair; Fang memorialized a law for examining achievement and checking officials.", idiomatic: "\" An edict had Fang compose this affair; Fang memorialized a law for examining achievement and checking officials." },
  { zh: "上令公卿朝臣與房會議溫室，皆以房言煩碎，令上下相司，不可許；", literal: "The emperor ordered dukes, ministers, and court officials to meet with Fang at the greenhouse; all considered Fang's words trivial and minute, making superiors and inferiors mutually surveil—could not be approved;", idiomatic: "The emperor ordered dukes, ministers, and court officials to meet with Fang at the greenhouse; all considered Fang's words trivial and minute, making superiors and inferiors mutually surveil—could not be approved;" },
  { zh: "上意鄉之。", literal: "the emperor's mind inclined toward it.", idiomatic: "the emperor's mind inclined toward it." },
  { zh: "時部刺史奏事京師，上召見諸刺史，令房曉以課事；", literal: "At that time regional inspectors were memorializing at the capital; the emperor summoned the inspectors and had Fang explain the checking affair;", idiomatic: "At that time regional inspectors were memorializing at the capital; the emperor summoned the inspectors and had Fang explain the checking affair;" },
  { zh: "剌史復以為不可行。", literal: "the inspectors again considered it impossible to carry out.", idiomatic: "the inspectors again considered it impossible to carry out." },
  { zh: "唯御史大夫鄭弘、光祿大夫周堪初言不可。", literal: "Only Censor-in-Chief Zheng Hong and Household Grandee Zhou Kan at first said it could not be done.", idiomatic: "Only Censor-in-Chief Zheng Hong and Household Grandee Zhou Kan at first said it could not be done." },
  { zh: "後善之。", literal: "Later they approved it.", idiomatic: "Later they approved it." },
  { zh: "是時，中書令石顯顓權，顯友人五鹿充宗為尚書令，二人用事。", literal: "At this time Palace Secretariat Director Shi Xian monopolized power; Xian's friend Wu Lu Chongzong was Secretariat Director; the two men held affairs.", idiomatic: "At this time Palace Secretariat Director Shi Xian monopolized power; Xian's friend Wu Lu Chongzong was Secretariat Director; the two men held affairs." },
  { zh: "房嘗宴見，問上曰：「幽、厲之君何以危？", literal: "Fang once was received at a banquet and asked the emperor: \"How did the rulers You and Li come to peril?", idiomatic: "Fang once was received at a banquet and asked the emperor: \"How did the rulers You and Li come to peril?" },
  { zh: "所任者何人也？", literal: "Whom did they employ?", idiomatic: "Whom did they employ?" },
  { zh: "」上曰：「君不明而所任者巧佞。", literal: "\" The emperor said: \"The ruler was not clear-sighted and those employed were clever flatterers.", idiomatic: "\" The emperor said: \"The ruler was not clear-sighted and those employed were clever flatterers." },
  { zh: "」房曰：「知其巧佞而用之邪，將以為賢也？", literal: "\" Fang said: \"Knowing they were clever flatterers yet employing them—or taking them for worthy?", idiomatic: "\" Fang said: \"Knowing they were clever flatterers yet employing them—or taking them for worthy?" },
  { zh: "」上曰：「賢之。", literal: "\" The emperor said: \"Taking them for worthy.", idiomatic: "\" The emperor said: \"Taking them for worthy." },
  { zh: "」房曰：「然則今何以知其不賢也？", literal: "\" Fang said: \"Then how does one today know they are not worthy?", idiomatic: "\" Fang said: \"Then how does one today know they are not worthy?" },
  { zh: "」上曰：「以其時亂而君危知之。", literal: "\" The emperor said: \"Because at that time there was disorder and the ruler was in danger, they knew it.", idiomatic: "\" The emperor said, \"Because at that time there was disorder and the ruler was in danger, they knew it." },
  { zh: "」房曰：「若是，任賢必治，任不肖必亂，必然之道也。", literal: "\" Fang said: \"If so, employing the worthy must bring order, employing the unworthy must bring disorder—it is the inevitable Way.", idiomatic: "\" Fang said, \"If so, employing the worthy must bring order, employing the unworthy must bring disorder—it is the inevitable Way." },
  { zh: "幽、厲何不覺寤而更求賢，曷為卒任不肖以至於是？", literal: "Why did You of Zhou and Li not wake up and again seek the worthy—why in the end employ the unworthy until it came to this?", idiomatic: "Why did You of Zhou and Li not wake up and again seek the worthy—why in the end employ the unworthy until it came to this?" },
  { zh: "」上曰：「臨亂之君，各賢其臣；", literal: "\" The emperor said: \"Rulers facing disorder each consider their ministers worthy;", idiomatic: "\" The emperor said, \"Rulers facing disorder each consider their ministers worthy;" },
  { zh: "令皆覺寤，天下安得危亡之君！", literal: "if all were to wake up, how would there be endangered and perishing rulers under Heaven!", idiomatic: "if all were to wake up, how would there be endangered and perishing rulers under Heaven!" },
  { zh: "」房曰：「齊桓公、秦二世亦嘗聞此君而非笑之；", literal: "\" Fang said: \"Duke Huan of Qi and Qin Er Shi also once heard of such rulers and indeed did not laugh at them;", idiomatic: "\" Fang said, \"Duke Huan of Qi and Qin Er Shi also once heard of such rulers and indeed did not laugh at them;" },
  { zh: "然則任豎刁、趙高，政治日亂，盜賊滿山，何不以幽、厲卜之而覺寤乎？", literal: "yet they employed Shu Diao and Zhao Gao, government daily grew chaotic, bandits filled the mountains—why did they not take You and Li as oracle and wake up?\"", idiomatic: "yet they employed Shu Diao and Zhao Gao, government daily grew chaotic, bandits filled the mountains—why did they not take You and Li as oracle and wake up?\"" },
  { zh: "」上曰：「唯有道者能以往知來耳。", literal: "\" The emperor said: \"Only one who has the Way can know the future from the past.\"", idiomatic: "\" The emperor said, \"Only one who has the Way can know the future from the past.\"" },
  { zh: "」房因免冠頓首曰：「《春秋》紀二百四十二年災異，以示萬世之君。", literal: "\" Fang thereupon removed his cap and knocked his head on the ground, saying: \"The Spring and Autumn Annals records two hundred forty-two years of portents and anomalies, to show rulers of ten thousand generations.", idiomatic: "\" Fang thereupon removed his cap and knocked his head on the ground, saying, \"The Spring and Autumn Annals records two hundred forty-two years of portents and anomalies, to show rulers of ten thousand generations." },
  { zh: "今陛下即位已來，日月失明，星辰逆行，山崩，泉湧，地震，石隕，夏霜，冬雷，春凋，秋榮，隕霜不殺，水，旱，螟蟲，民人饑、疫，盜賊不禁，刑人滿市，《春秋》所記災異盡備。", literal: "Since Your Majesty took the throne, sun and moon have lost their light, stars have run backward, mountains have collapsed, springs have gushed forth, the earth has quaked, stones have fallen, summer frost has appeared, winter thunder has sounded, spring withered, autumn flourished, falling frost did not kill, flood and drought, borer insects, the people have suffered famine and pestilence, bandits have not been restrained, and punished men fill the market—all the portents and anomalies recorded in the Spring and Autumn Annals are complete.", idiomatic: "Since Your Majesty took the throne, sun and moon have lost their light, stars have run backward, mountains have collapsed, springs have gushed forth, the earth has quaked, stones have fallen, summer frost has appeared, winter thunder has sounded, spring withered while autumn flourished, falling frost did not kill, floods and droughts, borer insects, the people have suffered famine and pestilence, bandits have not been restrained, and punished men fill the market—all the portents and anomalies recorded in the Spring and Autumn Annals are complete." },
  { zh: "陛下視今為治邪，亂邪？", literal: "Does Your Majesty regard the present as order or as disorder?\"", idiomatic: "Does Your Majesty regard the present as order or as disorder?\"" },
  { zh: "」上曰：「亦極亂耳，尚何道！", literal: "\" The emperor said: \"It is also extreme disorder—what more is there to say!", idiomatic: "\" The emperor said, \"It is also extreme disorder—what more is there to say!" },
  { zh: "」房曰：「今所任用者誰與？", literal: "\" Fang said: \"Whom are you now employing?\"", idiomatic: "\" Fang said, \"Whom are you now employing?\"" },
  { zh: "」上曰：「然，幸其愈於彼，又以為不在此人也。", literal: "\" The emperor said: \"So it is—I am fortunate they are better than those, and I also think it is not this man.\"", idiomatic: "\" The emperor said, \"So it is—I am fortunate they are better than those, and I also think it is not this man.\"" },
  { zh: "」房曰：「夫前世之君，亦皆然矣。", literal: "\" Fang said: \"Former rulers were all likewise.", idiomatic: "\" Fang said, \"Former rulers were all likewise." },
  { zh: "臣恐後之視今，猶今之視前也！", literal: "Your servant fears that those later will view the present as the present views the past!\"", idiomatic: "Your servant fears that those later will view the present as the present views the past!\"" },
  { zh: "」上良久，乃曰：「今為亂者誰哉？", literal: "\" The emperor was silent a long while, then said: \"Who now causes the disorder?\"", idiomatic: "\" The emperor was silent a long while, then said, \"Who now causes the disorder?\"" },
  { zh: "」房曰：「明主宜自知之。", literal: "\" Fang said: \"An enlightened ruler ought to know it himself.", idiomatic: "\" Fang said, \"An enlightened ruler ought to know it himself." },
  { zh: "」上曰：「不知也。", literal: "\" The emperor said: \"I do not know.", idiomatic: "\" The emperor said, \"I do not know." },
  { zh: "如知，何故用之！", literal: "If I knew, why would I employ him!\"", idiomatic: "If I knew, why would I employ him!\"" },
  { zh: "」房曰：「上最所信任，與圖事帷幄之中，進退天下之士者是矣。", literal: "\" Fang said: \"The one Your Majesty trusts most, who plots affairs within the curtain, and advances and dismisses the worthies of the empire—that is he.", idiomatic: "\" Fang said, \"The one Your Majesty trusts most, who plots affairs within the curtain and advances and dismisses the worthies of the empire—that is he." },
  { zh: "」房指謂石顯，上亦知之，謂房曰：「已諭。", literal: "\" Fang pointed and meant Shi Xian; the emperor also knew it and said to Fang: \"I have understood.\"", idiomatic: "\" Fang pointed and meant Shi Xian; the emperor also knew it and said to Fang, \"I have understood.\"" },
  { zh: "」房罷出，後上亦不能退顯也。", literal: "\" Fang withdrew; afterward the emperor still could not dismiss Xian.", idiomatic: "\" Fang withdrew; afterward the emperor still could not dismiss Xian." },
  { zh: ":臣光曰：人君之德不明，則臣下雖欲竭忠，何自而入乎！", literal: ": Your servant Guang says: When a ruler's virtue is not clear, though his ministers wish to exhaust their loyalty, by what path can they enter!", idiomatic: ": Your servant Guang says: When a ruler's virtue is not clear, though his ministers wish to exhaust their loyalty, by what path can they enter!" },
  { zh: "觀京房之所以曉孝元，可謂明白切至矣，而終不能寤，悲夫！", literal: "Observing how Jing Fang awakened Emperor Xiao Yuan, it may be called clear, direct, and to the point—yet in the end he could not be awakened; how sad!", idiomatic: "Observing how Jing Fang awakened Emperor Yuan, it may be called clear, direct, and to the point—yet in the end he could not be awakened; how sad!" },
  { zh: "《詩》曰：「匪面命之，言提其耳。", literal: "The Odes says: \"Not with the face commanding him—words lift his ear.", idiomatic: "The Odes says, \"Not with the face commanding him—words lift his ear." },
  { zh: "匪手攜之，言示之事。", literal: "Not with the hand leading him—words show him the matter.", idiomatic: "Not with the hand leading him—words show him the matter." },
  { zh: "」又曰：「誨爾諄諄，聽我藐藐。", literal: "\" It also says: \"I instruct you earnestly, yet you heed me lightly.\"", idiomatic: "\" It also says, \"I instruct you earnestly, yet you heed me lightly.\"" },
  { zh: "」孝元之謂矣！", literal: "\" This describes Emperor Xiao Yuan!", idiomatic: "\" This describes Emperor Yuan!" },
  { zh: "----5上令房上弟子曉知考功、課吏事者，欲試用之。", literal: "----5 The emperor ordered Fang to present disciples who understood examination of merit and evaluation of officials' affairs, wishing to try employing them.", idiomatic: "----5 The emperor ordered Fang to present disciples who understood examination of merit and evaluation of officials' affairs, wishing to try employing them." },
  { zh: "房上「中郎任良、姚平，願以為刺史，試考功法；", literal: "Fang presented \"Palace Gentlemen Ren Liang and Yao Ping—I wish to make them regional inspectors and try the method of examining merit;", idiomatic: "Fang presented \"Palace Gentlemen Ren Liang and Yao Ping—I wish to make them regional inspectors and try the method of examining merit;" },
  { zh: "臣得通籍殿中，為奏事，以防壅塞。", literal: "your servant may have registry access in the palace to memorialize affairs, to guard against obstruction.\"", idiomatic: "your servant may have registry access in the palace to memorialize affairs, to guard against obstruction.\"" },
  { zh: "」石顯、五鹿充宗皆疾房，欲遠之，建言，宜試以房為郡守。", literal: "\" Shi Xian and Wulu Chongzong both resented Fang and wished to send him far away; they proposed that Fang ought to be tried as a commandery administrator.", idiomatic: "\" Shi Xian and Wulu Chongzong both resented Fang and wished to send him far away; they proposed that Fang ought to be tried as a commandery administrator." },
  { zh: "帝於是以房為魏郡太守，得以考功法治郡。", literal: "The emperor thereupon made Fang Administrator of Wei Commandery, enabling him to govern the commandery by the law of examining merit.", idiomatic: "The emperor thereupon made Fang Administrator of Wei Commandery, enabling him to govern the commandery by the law of examining merit." },
  { zh: "房自請：「歲竟，乘傳奏事。", literal: "Fang himself requested: \"At year's end, I shall ride the post relay and memorialize affairs.", idiomatic: "Fang himself requested, \"At year's end, I shall ride the post relay and memorialize affairs." },
  { zh: "」天子許焉。", literal: "\" The Son of Heaven assented.", idiomatic: "\" The emperor assented." },
  { zh: "房自知數以論議為大臣所非，與石顯等有隙，不欲遠離左右，乃上封事曰：「臣出之後，恐為用事所蔽，身死而功不成，故願歲盡乘傳奏事，蒙哀見許。", literal: "Fang knew he had repeatedly been faulted by great ministers for his discourses and had a rift with Shi Xian and the rest; he did not wish to leave the emperor's side and therefore submitted a sealed memorial saying: \"After your servant goes out, I fear I will be screened by those in power, die in body while achievement is not accomplished—therefore I wished at year's end to ride the post relay and memorialize; I received compassion and was permitted.", idiomatic: "Fang knew he had repeatedly been faulted by great ministers for his discourses and had a rift with Shi Xian and the rest; he did not wish to leave the emperor's side and therefore submitted a sealed memorial saying, \"After your servant goes out, I fear I will be screened by those in power, die in body while achievement is not accomplished—therefore I wished at year's end to ride the post relay and memorialize; I received compassion and was permitted." },
  { zh: "乃辛已，蒙氣復乘卦，太陽侵色，此上大夫覆陽而上意疑也。", literal: "Then on xinsi, obscuring qi again rode the hexagram, the great sun invaded its color—this is the upper great officer overturning yang while the superior's intent is doubtful.", idiomatic: "Then on xinsi, obscuring qi again rode the hexagram, the great sun invaded its color—this is the upper great officer overturning yang while the superior's intent is doubtful." },
  { zh: "己卯、庚辰之間，必有欲隔絕臣，令不得乘傳奏事者。", literal: "Between jimao and gengchen there will certainly be one who wishes to cut your servant off and prevent him from riding the post relay to memorialize.\"", idiomatic: "Between jimao and gengchen there will certainly be one who wishes to cut your servant off and prevent him from riding the post relay to memorialize.\"" },
  { zh: "房未發，上令陽平侯王鳳承製詔房止無乘傳奏事。", literal: "Before Fang set out, the emperor ordered Marquis of Yangping Wang Feng to receive the edict and tell Fang to stop and not ride the post relay to memorialize.", idiomatic: "Before Fang set out, the emperor ordered Marquis of Yangping Wang Feng to receive the edict and tell Fang to stop and not ride the post relay to memorialize." },
  { zh: "房意愈恐。", literal: "Fang's mind grew ever more fearful.", idiomatic: "Fang grew ever more fearful." },
  { zh: "秋，房去至新豐，因郵上封事曰：「臣前以六月中言《遁卦》不效，法曰：『道人始去，寒湧水為災。", literal: "In autumn, as Fang departed and reached Xinfeng, he submitted a sealed memorial by post, saying: \"Your servant before said in the sixth month that the Dun hexagram would not take effect. The method says: 'When the man of the Way first departs, cold gushing water becomes disaster.", idiomatic: "In autumn, as Fang departed and reached Xinfeng, he submitted a sealed memorial by post, saying, \"Your servant before said in the sixth month that the Dun hexagram would not take effect. The method says, 'When the man of the Way first departs, cold gushing water becomes disaster." },
  { zh: "』至其七月，湧水出。", literal: "' When the seventh month came, gushing water appeared.", idiomatic: "' When the seventh month came, gushing water appeared." },
  { zh: "臣弟子姚平謂臣曰：『房可謂知道，未可謂信道也。", literal: "Your servant's disciple Yao Ping said to your servant: 'Fang may be called one who knows the Way, but not yet one who trusts the Way.", idiomatic: "Your servant's disciple Yao Ping said to your servant, 'Fang may be called one who knows the Way, but not yet one who trusts the Way." },
  { zh: "房言災異，未嘗不中。", literal: "Fang speaks of portents and anomalies and has never missed.", idiomatic: "Fang speaks of portents and anomalies and has never missed." },
  { zh: "湧水已出，道人當逐死，尚復何言！", literal: "Gushing water has already appeared—the man of the Way ought to be driven to death; what more is there to say!'", idiomatic: "Gushing water has already appeared—the man of the Way ought to be driven to death; what more is there to say!'" },
  { zh: "』臣曰：『陛下至仁，於臣尤厚，雖言而死，臣猶言也。", literal: "' Your servant said: 'Your Majesty is utmostly benevolent and especially generous to your servant; though I speak and die, your servant still speaks.'", idiomatic: "' Your servant said, 'Your Majesty is utmostly benevolent and especially generous to your servant; though I speak and die, your servant still speaks.'" },
  { zh: "』平又曰：『房可謂小忠，未可謂大忠也。", literal: "' Ping again said: 'Fang may be called small loyalty, but not yet great loyalty.", idiomatic: "' Ping again said, 'Fang may be called small loyalty, but not yet great loyalty." },
  { zh: "昔秦時趙高用事，有正先者，非刺高而死，高威自此成，故秦之亂，正先趣之。", literal: "In former times under Qin, when Zhao Gao held power, there was Zheng Xian, who criticized and stabbed Gao and died; Gao's authority from this was accomplished—thus Qin's disorder, Zheng Xian hastened it.'", idiomatic: "In former times under Qin, when Zhao Gao held power, there was Zheng Xian, who criticized and stabbed Gao and died; Gao's authority from this was accomplished—thus Qin's disorder, Zheng Xian hastened it.'" },
  { zh: "』今臣得出守郡，自詭效功，恐未效而死，惟陛下毋使臣塞湧水之異，當正先之死，為姚平所笑。", literal: "' Now your servant is able to go out and hold a commandery, presenting himself to offer achievement—I fear that before achievement is effected I will die; only may Your Majesty not make your servant block the anomaly of gushing water and meet Zheng Xian's death, to be laughed at by Yao Ping.\"", idiomatic: "' Now your servant is able to go out and hold a commandery, presenting himself to offer achievement—I fear that before achievement is effected I will die; only may Your Majesty not make your servant block the anomaly of gushing water and meet Zheng Xian's death, to be laughed at by Yao Ping.\"" },
  { zh: "房至陝，復上封事曰：「臣前白願出任良試考功，臣得居內。", literal: "When Fang reached Shan, he again submitted a sealed memorial, saying: \"Your servant before reported wishing to send out Ren Liang to try examining merit while your servant remained within.", idiomatic: "When Fang reached Shan, he again submitted a sealed memorial, saying, \"Your servant before reported wishing to send out Ren Liang to try examining merit while your servant remained within." },
  { zh: "議者知如此於身不利，臣不可蔽，故云『使弟子不若試師。", literal: "Deliberators knew that thus was not advantageous to your servant's person; your servant could not screen it—therefore they said 'Send the disciple rather than try the master.'", idiomatic: "Deliberators knew that thus was not advantageous to your servant's person; your servant could not screen it—therefore they said 'Send the disciple rather than try the master.'" },
  { zh: "』臣為刺史，又當奏事，故復云『為刺史，恐太守不與同心，不若以為太守。", literal: "' Your servant as regional inspector would again have to memorialize affairs—therefore they again said 'As regional inspector, I fear the administrator will not be of one mind; better to make him administrator.'", idiomatic: "' Your servant as regional inspector would again have to memorialize affairs—therefore they again said 'As regional inspector, I fear the administrator will not be of one mind; better to make him administrator.'" },
  { zh: "』此其所以隔絕臣也。", literal: "' This is how they cut your servant off.", idiomatic: "' This is how they cut your servant off." },
  { zh: "陛下不違其言而遂聽之，此乃蒙氣所以不解、太陽無色者也。", literal: "Your Majesty did not go against their words and thereupon followed them—this is why obscuring qi is not released and the great sun has no color.", idiomatic: "Your Majesty did not go against their words and thereupon followed them—this is why obscuring qi is not released and the great sun has no color." },
  { zh: "臣去稍遠，太陽侵色益甚，唯陛下毋難還臣而易逆天意。", literal: "As your servant goes somewhat farther, the great sun's invasion of color grows ever worse—only may Your Majesty not find it hard to return your servant and lightly go against Heaven's intent.", idiomatic: "As your servant goes somewhat farther, the great sun's invasion of color grows ever worse—only may Your Majesty not find it hard to return your servant and lightly go against Heaven's intent." },
  { zh: "邪說雖安於人，天氣必變，故人可欺，天不可欺也，願陛下察焉。", literal: "Perverse words may comfort men, but Heaven's qi must change—thus men may be deceived, Heaven may not be deceived; I wish Your Majesty to examine this.\"", idiomatic: "Perverse words may comfort men, but Heaven's qi must change—thus men may be deceived, Heaven may not be deceived; I wish Your Majesty to examine this.\"" },
  { zh: "房去月餘，竟徵下獄。", literal: "More than a month after Fang departed, he was in the end summoned and imprisoned.", idiomatic: "More than a month after Fang departed, he was in the end summoned and imprisoned." },
  { zh: "初，淮陽憲王舅張博，傾巧無行，多從王求金錢，欲為王求入朝。", literal: "Initially Zhang Bo, maternal uncle of Prince Xian of Huaiyang, was crafty and without conduct; he often sought gold and cash from the prince, wishing to seek an audience at court for the prince.", idiomatic: "Initially Zhang Bo, maternal uncle of Prince Xian of Huaiyang, was crafty and without conduct; he often sought gold and cash from the prince, wishing to seek an audience at court for the prince." },
  { zh: "博從京房學，以女妻房。", literal: "Bo studied with Jing Fang and gave his daughter in marriage to Fang.", idiomatic: "Bo studied with Jing Fang and gave his daughter in marriage to Fang." },
  { zh: "房每朝見，退輒為博道其語。", literal: "Whenever Fang attended court audience, on retiring he would tell Bo his words.", idiomatic: "Whenever Fang attended court audience, on retiring he would tell Bo his words." },
  { zh: "博因記房所說密語，令房為王作求朝奏草，皆持柬與王，以為信驗。", literal: "Bo thereupon recorded Fang's confidential words, had Fang draft a memorial seeking audience for the prince, and all were held in bamboo slips and given to the prince as proof and verification.", idiomatic: "Bo thereupon recorded Fang's confidential words, had Fang draft a memorial seeking audience for the prince, and all were held in bamboo slips and given to the prince as proof and verification." },
  { zh: "石顯知之，告『房與張博通謀，非謗政治，歸惡天子，詿誤諸侯王。", literal: "Shi Xian learned of it and reported 'Fang and Zhang Bo conspired together, slandered government, attributed evil to the Son of Heaven, and misled the feudal kings.", idiomatic: "Shi Xian learned of it and reported 'Fang and Zhang Bo conspired together, slandered government, attributed evil to the Son of Heaven, and misled the feudal kings." },
  { zh: "』皆下獄，棄市，妻子徙邊。", literal: "' All were imprisoned, executed in the market, and wives and children were banished to the frontier.", idiomatic: "' All were imprisoned, executed in the market, and wives and children were banished to the frontier." },
  { zh: "鄭弘坐與房善，免為庶人。", literal: "Zheng Hong sat in guilt for being friendly with Fang and was dismissed as a commoner.", idiomatic: "Zheng Hong was punished for being friendly with Fang and was dismissed as a commoner." },
  { zh: "----6御史中丞陳鹹數毀石顯，久之，坐與槐裡令朱雲善，漏洩省中語，石顯微伺知之，與雲皆下獄，髡為城旦。", literal: "----6 Censor-in-Chief Chen Xian repeatedly denounced Shi Xian; after a long while he sat in guilt for being friendly with Zhu Yun, magistrate of Huaili, and leaking words from within the Secretariat; Shi Xian secretly observed and learned of it—both he and Yun were imprisoned and shaved to serve as corvee laborers.", idiomatic: "----6 Censor-in-Chief Chen Xian repeatedly denounced Shi Xian; after a long while he was punished for being friendly with Zhu Yun, magistrate of Huaili, and leaking words from within the Secretariat; Shi Xian secretly observed and learned of it—both he and Yun were imprisoned and shaved to serve as corvee laborers." },
  { zh: "石顯威權日盛，公卿以下畏顯，重足一跡。", literal: "Shi Xian's awesome authority daily grew; from the Three Dukes down all feared Xian and stepped as if on overlapping feet with one footprint.", idiomatic: "Shi Xian's awesome authority daily grew; from the Three Dukes down all feared Xian and stepped as if on overlapping feet with one footprint." },
  { zh: "顯與中書僕射牢梁、少府五鹿充宗結為黨友，諸附倚者皆得寵位，民歌之曰：「牢邪！", literal: "Xian with Secretariat Vice Director Lao Liang and Privy Treasurer Wulu Chongzong formed a faction; all who leaned on them obtained favored posts, and the people sang: \"Lao, eh!", idiomatic: "Xian with Secretariat Vice Director Lao Liang and Privy Treasurer Wulu Chongzong formed a faction; all who leaned on them obtained favored posts, and the people sang, \"Lao, eh!" },
  { zh: "石邪！", literal: "Shi, eh!", idiomatic: "Shi, eh!" },
  { zh: "五鹿客邪！", literal: "Wulu's guests, eh!", idiomatic: "Wulu's guests, eh!" },
  { zh: "印何纍纍，綬若若邪！", literal: "How piled are the seals, how many the ribbons, eh!\"", idiomatic: "How piled are the seals, how many the ribbons, eh!\"" },
  { zh: "顯內自知擅權，專柄在掌握，恐天子一旦納用左右耳目以間己，乃時歸誠，取一信以為驗。", literal: "Within himself Xian knew he monopolized authority and held the handle in his palm; he feared that one day the Son of Heaven would adopt the eyes and ears at his side to come between him and power—therefore he at times returned to sincerity and took one proof as verification.", idiomatic: "Within himself Xian knew he monopolized authority and held the handle in his palm; he feared that one day the emperor would adopt the eyes and ears at his side to come between him and power—therefore he at times returned to sincerity and took one proof as verification." },
  { zh: "顯嘗使至諸官，有所徵發，顯先自白：「恐後漏盡宮門閉，請使詔吏開門。", literal: "Xian once sent someone to the various offices for a requisition; Xian first reported himself: \"I fear that later, when the clepsydra is exhausted and palace gates are closed, I ask that an edict be sent to the clerks to open the gates.\"", idiomatic: "Xian once sent someone to the various offices for a requisition; Xian first reported himself, \"I fear that later, when the clepsydra is exhausted and palace gates are closed, I ask that an edict be sent to the clerks to open the gates.\"" },
  { zh: "」上許之。", literal: "\" The emperor assented.", idiomatic: "\" The emperor assented." },
  { zh: "顯故投夜還，稱詔開門入。", literal: "Xian deliberately returned at night, declared an edict, and had the gates opened to enter.", idiomatic: "Xian deliberately returned at night, declared an edict, and had the gates opened to enter." },
  { zh: "後果有上書告「顯顓命，矯詔開宮門」，天子聞之，笑以其書示顯。", literal: "Afterward there truly was a memorial reporting \"Xian's arbitrary orders and forged edict opening palace gates\"; the Son of Heaven heard it and, laughing, showed the document to Xian.", idiomatic: "Afterward there truly was a memorial reporting \"Xian's arbitrary orders and forged edict opening palace gates\"; the emperor heard it and, laughing, showed the document to Xian." },
  { zh: "顯因泣曰：「陛下過私小臣，屬任以事，群下無不嫉妒，欲陷害臣者，事類如此非一，唯獨明主知之。", literal: "Xian thereupon wept and said: \"Your Majesty excessively favors your petty servant and entrusts him with affairs; none below are not jealous—those who wish to trap your servant, matters like this are not one alone; only the enlightened ruler knows.", idiomatic: "Xian thereupon wept and said, \"Your Majesty excessively favors your petty servant and entrusts him with affairs; none below are not jealous—those who wish to trap your servant, matters like this are not one alone; only the enlightened ruler knows." },
  { zh: "愚臣微賤，誠不能以一軀稱快萬眾，任天下之怨。", literal: "Your foolish servant is slight and base and truly cannot with one body satisfy the myriad masses or bear the empire's resentments.", idiomatic: "Your foolish servant is slight and base and truly cannot with one body satisfy the myriad masses or bear the empire's resentments." },
  { zh: "臣願歸樞機職，受後宮掃除之役，死無所恨。", literal: "Your servant wishes to return to duties at the pivot and accept service sweeping the rear palace—death would hold no regret.", idiomatic: "Your servant wishes to return to duties at the pivot and accept service sweeping the rear palace—death would hold no regret." },
  { zh: "唯陛下哀憐財幸，以此全活小臣。", literal: "Only may Your Majesty pity and favor with resources, and by this fully preserve your petty servant's life.\"", idiomatic: "Only may Your Majesty pity and favor with resources, and by this fully preserve your petty servant's life.\"" },
  { zh: "」天子以為然而憐之，數勞勉顯，加厚賞賜，賞賜及賂遺訾一萬萬。", literal: "\" The Son of Heaven thought it so and pitied him; repeatedly he comforted and encouraged Xian, adding thick rewards and gifts—rewards, gifts, and bribes together reached one hundred million.", idiomatic: "\" The emperor thought it so and pitied him; repeatedly he comforted and encouraged Xian, adding thick rewards and gifts—rewards, gifts, and bribes together reached one hundred million." },
  { zh: "初，顯聞眾人匈匈，言己殺前將軍蕭望之，恐天下學士訕己，以諫大夫貢禹明經箸節，乃使人致意，深自結納，因薦禹天子，歷位九卿，禮事之甚備。", literal: "Initially Xian heard the masses in uproar saying he had killed former General Xiao Wangzhi and feared scholars throughout the empire would ridicule him; because Remonstrance Grandee Gong Yu was versed in the classics with marked integrity, he sent someone to convey his regard, deeply joined and drew him in, and thereby recommended Yu to the Son of Heaven—he rose through the Nine Ministers and was honored with utmost completeness.", idiomatic: "Initially Xian heard the masses in uproar saying he had killed former General Xiao Wangzhi and feared scholars throughout the empire would ridicule him; because Remonstrance Grandee Gong Yu was versed in the classics with marked integrity, he sent someone to convey his regard, deeply joined and drew him in, and thereby recommended Yu to the emperor—he rose through the Nine Ministers and was honored with utmost completeness." },
  { zh: "議者於是或稱顯，以為不妒譖望之矣。", literal: "Deliberators thereupon sometimes praised Xian, thinking he did not envy and slander Wangzhi.", idiomatic: "Deliberators thereupon sometimes praised Xian, thinking he did not envy and slander Wangzhi." },
  { zh: "顯之設變詐以自解免，取信人主者，皆此類也。", literal: "Xian's setting up shifts and fraud to extricate himself and gain the ruler's trust were all of this kind.", idiomatic: "Xian's setting up shifts and fraud to extricate himself and gain the ruler's trust were all of this kind." },
  { zh: ":荀悅曰：夫佞臣之惑君主也甚矣，故孔子曰：「遠佞人。", literal: ": Xun Yue says: How greatly flatterers bewilder their rulers! Therefore Confucius said: \"Keep flatterers at a distance.", idiomatic: ": Xun Yue says: How greatly flatterers bewilder their rulers! Therefore Confucius said, \"Keep flatterers at a distance." },
  { zh: "」非但不用而已，乃遠而絕之，隔塞其源，戒之極也。", literal: "\" Not only not employ them, but keep them far off and cut them off, block their source—this is the utmost of caution.", idiomatic: "\" Not only not employ them, but keep them far off and cut them off, block their source—this is the utmost of caution." },
  { zh: "孔子曰：「政者，正也。", literal: "Confucius said: \"Government is correctness.", idiomatic: "Confucius said, \"Government is correctness." },
  { zh: "」夫要道之本，正己而已矣。", literal: "\" The root of the essential Way is only to correct oneself.", idiomatic: "\" The root of the essential Way is only to correct oneself." },
  { zh: "平直真實者，正之主也。", literal: "The straight, level, true, and real are the masters of correctness.", idiomatic: "The straight, level, true, and real are the masters of correctness." },
  { zh: "故德必核其真，然後授其位；", literal: "Therefore virtue must be examined for its truth, and only then is office conferred;", idiomatic: "Therefore virtue must be examined for its truth, and only then is office conferred;" },
  { zh: "能必核其真，然後授其事；", literal: "ability must be examined for its truth, and only then is duty conferred;", idiomatic: "ability must be examined for its truth, and only then is duty conferred;" },
  { zh: "功必核其真，然後授其賞；", literal: "merit must be examined for its truth, and only then is reward conferred;", idiomatic: "merit must be examined for its truth, and only then is reward conferred;" },
  { zh: "罪必核其真，然後授其刑；", literal: "guilt must be examined for its truth, and only then is punishment conferred;", idiomatic: "guilt must be examined for its truth, and only then is punishment conferred;" },
  { zh: "行必核其真，然後貴之；", literal: "conduct must be examined for its truth, and only then is it honored;", idiomatic: "conduct must be examined for its truth, and only then is it honored;" },
  { zh: "言必核其真，然後信之；", literal: "words must be examined for their truth, and only then are they trusted;", idiomatic: "words must be examined for their truth, and only then are they trusted;" },
  { zh: "物必核其真，然後用之；", literal: "things must be examined for their truth, and only then are they used;", idiomatic: "things must be examined for their truth, and only then are they used;" },
  { zh: "事必核其真，然後修之。", literal: "affairs must be examined for their truth, and only then are they carried out.", idiomatic: "affairs must be examined for their truth, and only then are they carried out." },
  { zh: "故眾正積於上，萬事實於下，先王之道，如斯而已矣！", literal: "Thus many correctnesses accumulate above and the myriad affairs are real below—the way of former kings is only thus!", idiomatic: "Thus many correctnesses accumulate above and the myriad affairs are real below—the way of former kings is only thus!" },
  { zh: "----7八月，癸亥，以光祿勳匡衡為御史大夫。", literal: "----7 In the eighth month, on guihai, Director of the Imperial Clan Kuang Heng was made Censor-in-Chief.", idiomatic: "----7 In the eighth month, on guihai, Director of the Imperial Clan Kuang Heng was made Censor-in-Chief." },
  { zh: "----8閏月，丁酉，太皇太后上官氏崩。", literal: "----8 In the intercalary month, on dingyou, Grand Empress Dowager Shangguan died.", idiomatic: "----8 In the intercalary month, on dingyou, Grand Empress Dowager Shangguan died." },
  { zh: "----9冬，十一月，齊、楚地震，大雨雪，樹折，屋壞。", literal: "----9 In winter, the eleventh month, Qi and Chu had earthquakes, great rain and snow; trees broke and houses were ruined.", idiomatic: "----9 In winter, the eleventh month, Qi and Chu were shaken by earthquakes amid heavy rain and snow; trees snapped and houses collapsed." },
  { zh: "1夏，六月，甲辰，扶陽共侯韋玄成薨。", literal: "1 In summer, the sixth month, on day jiachen, the common marquis of Fuyang Wei Xuancheng died.", idiomatic: "1 In summer, the sixth month, on day jiachen, Common Marquis Wei Xuancheng of Fuyang died." },
  { zh: "----2秋，七月，匡衡為丞相。", literal: "----2 In autumn, the seventh month, Kuang Heng became chancellor.", idiomatic: "----2 In autumn, the seventh month, Kuang Heng became chancellor." },
  { zh: "戊辰，衛尉李延壽為御史大夫。", literal: "On day wuchen, Commandant of the Guards Li Yanshou became censor-in-chief.", idiomatic: "On day wuchen, Commandant of the Guards Li Yanshou became censor-in-chief." },
  { zh: "----3冬，使西域都護、騎都尉北地甘延壽、副校尉山陽陳湯共誅斬匈奴郅支單于於康居。", literal: "----3 In winter, he dispatched Protector-General of the Western Regions and Commandant of Cavalry Gan Yanshou of Beidi and Deputy Commandant Chen Tang of Shanyang jointly to execute and behead the Xiongnu Chanyu Zhizhi at Kangju.", idiomatic: "----3 In winter, Protector-General of the Western Regions and Commandant of Cavalry Gan Yanshou of Beidi and Deputy Commandant Chen Tang of Shanyang jointly executed and beheaded the Xiongnu chanyu Zhizhi at Kangju." },
  { zh: "始，郅支單于自以大國，威名尊重，又乘勝驕，不為康居王禮，怒殺康居王女及貴人、人民數百，或支解投都賴水中。", literal: "At the beginning, Chanyu Zhizhi, taking himself for a great state, was honored in prestige and name, and again, riding victory, was arrogant; he did not show the king of Kangju courtesy, angrily killed the king of Kangju's daughter and hundreds of nobles and common people, and some he dismembered and cast into the Dulai River.", idiomatic: "At the beginning, Chanyu Zhizhi, deeming himself ruler of a great power and honored in prestige, grew arrogant on the strength of his victories; he refused to show the king of Kangju proper courtesy, and in anger killed the king's daughter along with hundreds of nobles and commoners, some of whom he dismembered and cast into the Dulai River." },
  { zh: "發民作城，日作五百人，二歲乃已。", literal: "He drafted the people to build a city, five hundred men working each day; only after two years was it finished.", idiomatic: "He drafted the people to build a city, with five hundred laborers working each day; the work took two years to finish." },
  { zh: "又遣使責闔蘇、大宛諸國歲遺，不敢不予。", literal: "He again sent envoys to demand the annual tribute from the various states of Hesu and Dayuan; none dared not give.", idiomatic: "He again sent envoys to demand annual tribute from the various states of Hesu and Dayuan; none dared refuse." },
  { zh: "漢遣使三輩至康居，求谷吉等死，郅支困辱使者，不肯奉詔；", literal: "Han sent three missions to Kangju to demand justice for the death of Gu Ji and others; Zhizhi distressed and humiliated the envoys and would not obey the edict;", idiomatic: "Han sent three missions to Kangju to demand justice for the killing of Gu Ji and others; Zhizhi mistreated the envoys and refused to obey the imperial edict;" },
  { zh: "而因都護上書，言「居困厄，願歸計強漢，遣子入侍。", literal: "yet through the protector-general he submitted a memorial, saying, \"I dwell in distress and hardship and wish to turn and plan for mighty Han, sending my son to attend court.", idiomatic: "yet through the protector-general he submitted a memorial saying, \"I dwell in hardship and wish to turn toward mighty Han and send my son to attend court.\"" },
  { zh: "」其驕嫚如此。", literal: "\" His arrogance and insolence were like this.", idiomatic: "\" His arrogance and insolence were such." },
  { zh: "湯為人沉勇，有大慮，多策略，喜奇功，與延壽謀曰：「夷狄畏服大種，其天性也。", literal: "Tang was by nature deep and brave, with great foresight and many stratagems, fond of extraordinary achievement; he plotted with Yanshou, saying: \"The Yi and Di fear and submit to a great race—this is their inborn nature.", idiomatic: "Tang was deep and brave, with great foresight and many stratagems, and fond of extraordinary achievement; he plotted with Yanshou, saying, \"The barbarians fear and submit to a great power—this is their inborn nature.\"" },
  { zh: "西域本屬匈奴，今郅支單于威名遠聞，侵陵烏孫、大宛，常為康居畫計，欲降服之。", literal: "The Western Regions originally belonged to the Xiongnu; now Chanyu Zhizhi's prestige and name are heard far abroad; he encroaches on and bullies Wusun and Dayuan, constantly plotting plans for Kangju, wishing to bring them to submission.", idiomatic: "The Western Regions originally belonged to the Xiongnu; now Chanyu Zhizhi's fame reaches far abroad; he encroaches on Wusun and Dayuan, constantly plotting for Kangju, and wishes to bring them to submission." },
  { zh: "如得此二國，數年之間，城郭諸國危矣。", literal: "If he gains these two states, within a few years the walled states will be in peril.", idiomatic: "If he gains these two states, within a few years the walled states of the region will be in peril." },
  { zh: "且其人剽悍，好戰伐，數取勝，久畜之，必為西域患。", literal: "Moreover, his people are fierce and hardy, fond of war and campaigns, and repeatedly win victories; if long nourished, they are sure to become a scourge to the Western Regions.", idiomatic: "Moreover, his people are fierce and warlike, repeatedly victorious in battle; if allowed to grow strong over time, they will surely become a scourge to the Western Regions." },
  { zh: "雖所在絕遠，蠻夷無金城、強弩之守。", literal: "Although his seat is utterly remote, the barbarians have no metal walls or strong crossbows for defense.", idiomatic: "Although his seat is utterly remote, the barbarians have no walled cities or strong crossbows for defense." },
  { zh: "如發屯田吏士，驅從烏孫眾兵，直指其城下，彼亡則無所之，守則不足自保，千載之功可一朝而成也！", literal: "If we mobilize garrison-farmer officials and soldiers, drive and follow Wusun's massed troops straight to his walls, if they flee they will have nowhere to go, if they defend they will not suffice to protect themselves—a achievement of a thousand years can be accomplished in a single morning!", idiomatic: "If we mobilize garrison troops, drive Wusun's forces with them straight to his walls, they will have nowhere to flee if they run and will not suffice to defend themselves if they hold out—an achievement of a thousand years can be won in a single morning!\"" },
  { zh: "」延壽亦以為然，欲奏請之。", literal: "\" Yanshou also thought it right and wished to memorialize and request permission.", idiomatic: "\" Yanshou also agreed and wished to memorialize and request permission." },
  { zh: "湯曰：「國家與公卿議，大策非凡所見，事必不從。", literal: "Tang said: \"The state deliberates with the grandees; a great plan is not what ordinary men see—the matter is sure not to be followed.", idiomatic: "Tang said, \"The court will deliberate with the grandees on a plan of this scale, which ordinary men cannot grasp—the proposal is sure to be rejected.\"" },
  { zh: "」延壽猶與不聽。", literal: "\" Yanshou still did not agree to listen.", idiomatic: "\" Yanshou still would not agree." },
  { zh: "會其久病，湯獨矯制發城郭諸國兵、車師戊已校尉屯田吏士。", literal: "It happened that he was long ill; Tang alone forged an edict and mobilized the troops of the walled states, the garrison-farmer officials and soldiers of the Commandants of the Western Regions at Cheshi and Wuji.", idiomatic: "As it happened, Yanshou was long ill; Tang alone forged an edict and mobilized the troops of the walled states and the garrison troops of the Commandants of the Western Regions at Cheshi and Wuji." },
  { zh: "延壽聞之，驚起，欲止焉。", literal: "When Yanshou heard of it, he started up in alarm and wished to stop it.", idiomatic: "When Yanshou heard of it, he started up in alarm and wished to stop him." },
  { zh: "湯怒，按劍叱延壽曰：「大眾已集會，豎子欲沮眾邪！", literal: "Tang was enraged, pressed his sword and shouted at Yanshou: \"The great host is already assembled—do you, stripling, wish to discourage the masses!", idiomatic: "Tang was enraged, gripped his sword, and shouted at Yanshou, \"The great host is already assembled—do you, stripling, wish to discourage the army!\"" },
  { zh: "」延壽遂從之。", literal: "\" Yanshou thereupon followed him.", idiomatic: "\" Yanshou thereupon followed him." },
  { zh: "部勒行陳，漢兵、胡兵合四萬餘人。", literal: "He arrayed and ordered the marching formations; Han troops and barbarian troops together numbered more than forty thousand men.", idiomatic: "He arrayed the marching formations; Han and barbarian troops together numbered more than forty thousand men." },
  { zh: "延壽、湯上疏自劾奏矯制，陳言兵狀，即日引軍分行，別為六校：其三校從南道逾蔥嶺，逕大宛；", literal: "Yanshou and Tang submitted a memorial impeaching themselves for forging an edict, stating the military situation, and that same day led the army in separate columns, divided into six commands: three commands went by the southern route over the Onion Range straight to Dayuan;", idiomatic: "Yanshou and Tang submitted a memorial impeaching themselves for forging an edict and stating the military situation; that same day they led the army in separate columns divided into six commands: three commands took the southern route over the Onion Range straight to Dayuan;" },
  { zh: "其三校都護自將，發溫宿國，從北道入赤谷，過烏孫，涉康居界，至闐池西。", literal: "the other three commands the protector-general led in person, setting out from the state of Wensu, entering Red Valley by the northern route, passing through Wusun, crossing Kangju's border, and reaching west of Tianchi.", idiomatic: "the other three commands the protector-general led in person, setting out from Wensu, entering Red Valley by the northern route, passing through Wusun, crossing Kangju's border, and reaching west of Tianchi." },
  { zh: "而康居副王抱闐將數千騎寇赤谷城東，殺略大昆彌千餘人，驅畜產甚多，從後與漢軍相及，頗寇盜後重。", literal: "Meanwhile Kangju's deputy king Baotian led several thousand horsemen to raid east of Red Valley City, killing and plundering more than a thousand of the Great Kunmi's people and driving off very many livestock; coming up from behind with the Han army, he repeatedly raided and robbed the baggage train.", idiomatic: "Meanwhile Kangju's deputy king Baotian led several thousand horsemen to raid east of Red Valley City, killing and plundering more than a thousand of the Great Kunmi's followers and driving off large herds of livestock; falling in behind the Han army, he repeatedly raided the baggage train." },
  { zh: "湯縱胡兵擊之，殺四百六十人，得其所略民四百七十人，還付大昆彌，其馬、牛、羊以給軍食。", literal: "Tang loosed the barbarian troops to strike them, killing four hundred sixty men, recovering four hundred seventy of the people they had plundered and returning them to the Great Kunmi; their horses, cattle, and sheep were used to supply the army's food.", idiomatic: "Tang loosed the barbarian troops to attack them, killing four hundred sixty men, recovering four hundred seventy plundered people and returning them to the Great Kunmi; their horses, cattle, and sheep were used to supply the army." },
  { zh: "又捕得抱闐貴人伊奴毒。", literal: "He also captured Baotian's noble Yinudu.", idiomatic: "He also captured Baotian's noble Yinudu." },
  { zh: "入康居東界，令軍不得為寇。", literal: "On entering Kangju's eastern border, he ordered the army not to act as raiders.", idiomatic: "On entering Kangju's eastern border, he ordered the army not to plunder." },
  { zh: "間呼其貴人屠墨見之，諭以威信，與飲、盟，遣去。", literal: "He secretly summoned their noble Tumo to an audience, instructed him with authority and trust, drank and made covenant with him, and sent him away.", idiomatic: "He secretly summoned the Kangju noble Tumo to an audience, instructed him with authority and trust, drank and made covenant with him, and sent him away." },
  { zh: "徑引行，未至單于城可六十里，止營。", literal: "He led the march straight on; when still about sixty li from the chanyu's city, he halted and encamped.", idiomatic: "He marched straight on; when still about sixty li from the chanyu's city, he halted and encamped." },
  { zh: "復捕得康居貴人具色子男開牟以為導。", literal: "He again captured the Kangju noble Jusezi's son Nankaimou to serve as guide.", idiomatic: "He again captured the Kangju noble Jusezi's son Nankaimou to serve as guide." },
  { zh: "具色子，即屠墨母之弟，皆怨單于，由是具知郅支情。", literal: "Jusezi was Tumo's mother's younger brother; all resented the chanyu, and thereby fully knew Zhizhi's situation.", idiomatic: "Jusezi was Tumo's mother's younger brother; all resented the chanyu and thereby knew Zhizhi's situation in full." },
  { zh: "明日，引行，未至城三十里，止營。", literal: "The next day he led the march; when still thirty li from the city, he halted and encamped.", idiomatic: "The next day he marched on; when still thirty li from the city, he halted and encamped." },
  { zh: "單于遣使曰：「漢兵何以來？", literal: "The chanyu sent an envoy, saying: \"Why have Han troops come?", idiomatic: "The chanyu sent an envoy, saying, \"Why have Han troops come?\"" },
  { zh: "」應曰：「單于上書言：『居困厄，願歸計強漢，身入朝見，』天子哀閔單于棄大國，屈意康居，故使都護將軍來迎單于妻子。", literal: "\" They replied: \"The chanyu submitted a memorial saying, 'I dwell in distress and hardship and wish to turn and plan for mighty Han and come in person to audience at court.' The Son of Heaven pitied the chanyu for abandoning his great state and bending his will in Kangju, and therefore sent the protector-general to welcome the chanyu's wife and children.", idiomatic: "\" They replied, \"The chanyu submitted a memorial saying, 'I dwell in hardship and wish to turn toward mighty Han and come in person to audience at court.' The emperor pitied the chanyu for abandoning his great state and bending his will in Kangju, and therefore sent the protector-general to welcome the chanyu's wife and children.\"" },
  { zh: "恐左右驚動，故未敢至城下。", literal: "Fearing to startle those beside you, we have not yet dared to come below the walls.", idiomatic: "Fearing to startle your attendants, we have not yet dared to come below the walls.\"" },
  { zh: "」使數往來相答報，延壽、湯因讓之：「我為單于遠來，而至今無名王、大人見將軍受事者，何單于忽大計，失客主之禮也！", literal: "\" Envoys went back and forth several times answering one another; Yanshou and Tang thereupon reproached him: \"We have come far for the chanyu, yet to this day no noble king or great man has come out to meet the general and receive his commission—why does the chanyu neglect the great plan and lose the courtesy due host and guest!", idiomatic: "\" Envoys went back and forth several times; Yanshou and Tang thereupon reproached him, \"We have come far for the chanyu, yet to this day no noble king or great man has come out to meet the general and receive his commission—why does the chanyu neglect the great plan and fail the courtesy due host and guest!\"" },
  { zh: "兵來道遠，人畜罷極，食度且盡，恐無以自還，願單于與大臣審計策。", literal: "The troops have come by a distant road; men and livestock are utterly exhausted and provisions are nearly gone—we fear we will have no means to return ourselves; we wish the chanyu and his great ministers would carefully calculate the plan.", idiomatic: "The troops have come by a distant road; men and livestock are utterly exhausted and provisions are nearly gone—we fear we cannot return; we wish the chanyu and his great ministers would carefully weigh the plan.\"" },
  { zh: "明日，前至郅支城都賴水上，離城三里，止營傅陳。", literal: "The next day they advanced to Zhizhi's city on the Dulai River, three li from the city, halted, encamped, and spread their battle array.", idiomatic: "The next day they advanced to Zhizhi's city on the Dulai River, halted three li from the city, encamped, and spread their battle array." },
  { zh: "望見單于城上立五采幡幟，數百人被甲乘城；", literal: "They saw on the chanyu's walls five-colored banners and flags set up, and several hundred men in armor manning the walls;", idiomatic: "They saw five-colored banners and flags raised on the chanyu's walls and several hundred armored men manning them;" },
  { zh: "又出百餘騎往來馳城下，步兵百餘人夾門魚鱗陳，講習用兵。", literal: "more than a hundred horsemen also came out galloping back and forth below the walls; more than a hundred foot soldiers flanked the gate in fish-scale formation, drilling in the use of arms.", idiomatic: "more than a hundred horsemen galloped back and forth below the walls; more than a hundred foot soldiers flanked the gate in fish-scale formation, drilling in military maneuvers." },
  { zh: "城上人更招漢軍曰：「鬥來！", literal: "Men on the walls again called to the Han army: \"Come fight!", idiomatic: "Men on the walls again called to the Han army, \"Come fight!\"" },
  { zh: "」百餘騎馳赴營，營皆張弩持滿指之，騎引卻。", literal: "\" More than a hundred horsemen galloped toward the camp; the camp all drew crossbows full and aimed at them, and the horsemen drew back.", idiomatic: "\" More than a hundred horsemen galloped toward the camp; the camp drew crossbows full and aimed at them, and the horsemen withdrew." },
  { zh: "頗遣吏士射城門騎、步兵，騎、步兵皆入。", literal: "They repeatedly sent officials and soldiers to shoot at the horsemen and foot soldiers at the gate; horsemen and foot soldiers all went inside.", idiomatic: "They repeatedly sent men to shoot at the horsemen and foot soldiers at the gate until all had gone inside." },
  { zh: "延壽、湯令軍：「聞鼓音，皆薄城下，四面圍城，各有所守，穿塹，塞門戶，鹵楯為前，戟弩為後，仰射城樓上人。", literal: "Yanshou and Tang ordered the army: \"When you hear the drum, all press to below the walls, surround the city on four sides, each holding his assigned post, dig trenches, block gates and doors, with rattan shields in front and halberds and crossbows behind, shooting upward at the men on the towered walls.", idiomatic: "Yanshou and Tang ordered the army, \"When you hear the drum, all press to below the walls, surround the city on four sides, each hold his post, dig trenches, block gates and doors, with rattan shields in front and halberds and crossbows behind, and shoot upward at the men on the towered walls.\"" },
  { zh: "」樓上人下走。", literal: "\" The men on the towers came down and fled.", idiomatic: "\" The men on the towers came down and fled." },
  { zh: "土城外有重木城，從木城中射，頗殺傷外人。", literal: "Outside the earthen wall was a double wooden wall; shooting from within the wooden wall, they killed and wounded many of the outsiders.", idiomatic: "Outside the earthen wall was a double wooden wall; shooting from within it, they killed and wounded many of the attackers." },
  { zh: "外人發薪燒木城，夜，數百騎欲出，外迎射，殺之。", literal: "The outsiders piled fuel and burned the wooden wall; at night several hundred horsemen wished to come out; those outside met them with shooting and killed them.", idiomatic: "The attackers piled fuel and burned the wooden wall; at night several hundred horsemen tried to break out; those outside met them with arrows and killed them." },
  { zh: "初，單于聞漢兵至，欲去，疑康居怨己，為漢內應，又聞烏孫諸國兵皆發，自以無所之。", literal: "At first, when the chanyu heard Han troops had arrived, he wished to leave; he suspected Kangju resented him and would act as Han's inside response, and also heard that the various states of Wusun had all mobilized troops; he thought he had nowhere to go.", idiomatic: "At first, when the chanyu heard Han troops had arrived, he wished to flee; he suspected Kangju resented him and would act as Han's ally within, and also heard that Wusun and the other states had all mobilized; he thought he had nowhere to go." },
  { zh: "郅支已出，復還，曰：「不如堅守。", literal: "Zhizhi had already gone out but returned again, saying: \"It is better to hold firm.", idiomatic: "Zhizhi had already gone out but returned, saying, \"It is better to hold firm.\"" },
  { zh: "漢兵遠來，不能久攻。", literal: "Han troops have come from afar and cannot press the attack long.", idiomatic: "Han troops have come from afar and cannot press a long siege.\"" },
  { zh: "」單于乃被甲在樓上，諸閼氏、夫人數十皆以弓射外人。", literal: "\" The chanyu thereupon donned armor on the tower; the various yanzhi and several tens of ladies all shot at the outsiders with bows.", idiomatic: "\" The chanyu thereupon donned armor on the tower; the various consorts and several tens of ladies all shot at the attackers with bows." },
  { zh: "外人射中單于鼻，諸夫人頗死；", literal: "The outsiders shot and hit the chanyu's nose; many of the ladies died;", idiomatic: "The attackers shot the chanyu in the nose; many of the ladies were killed;" },
  { zh: "單于乃下。", literal: "the chanyu thereupon came down.", idiomatic: "the chanyu thereupon came down." },
  { zh: "夜過半，木城穿，中人卻入土城，乘城呼。", literal: "Past the middle of the night the wooden wall was breached; the men inside retreated into the earthen wall, mounted the wall, and shouted.", idiomatic: "Past midnight the wooden wall was breached; the defenders retreated into the earthen wall, mounted it, and shouted." },
  { zh: "時康居兵萬餘騎，分為十餘處，四面環城，亦與相應和。", literal: "At that time Kangju's troops were more than ten thousand horsemen, divided into more than ten groups, encircling the city on four sides, also answering and joining in chorus.", idiomatic: "At that time more than ten thousand Kangju horsemen, divided into more than ten groups, encircled the city on four sides and joined in answering shouts." },
  { zh: "夜，數奔營，不利，輒卻。", literal: "At night they several times charged the camp; it went ill and they would withdraw.", idiomatic: "At night they charged the camp several times without success and withdrew each time." },
  { zh: "平明，四面火起，吏士喜，大呼乘之，鉦、鼓聲動地。", literal: "At daybreak fires rose on four sides; officials and soldiers rejoiced, shouted loudly and pressed the advantage; gongs and drums shook the ground.", idiomatic: "At daybreak fires rose on four sides; the officers and soldiers rejoiced, shouted loudly and pressed the attack; gongs and drums shook the ground." },
  { zh: "康居兵引卻；", literal: "Kangju's troops drew back;", idiomatic: "Kangju's troops withdrew;" },
  { zh: "漢兵四面推鹵楯，並入土城中。", literal: "Han troops on four sides pushed rattan shields and together entered the earthen city.", idiomatic: "Han troops on four sides pushed rattan shields and together entered the earthen city." },
  { zh: "單于男女百餘人走入大內。", literal: "The chanyu's men and women, more than a hundred, ran into the great inner quarters.", idiomatic: "More than a hundred of the chanyu's men and women fled into the inner palace." },
  { zh: "漢兵縱火，吏士爭入，單于被創死。", literal: "Han troops set fires; officials and soldiers vied to enter; the chanyu was wounded and died.", idiomatic: "Han troops set fires; officers and soldiers vied to enter; the chanyu was wounded and died." },
  { zh: "軍候假丞杜勳斬單于首。", literal: "Acting assistant commandant of the army Du Xun beheaded the chanyu and took his head.", idiomatic: "Acting assistant commandant Du Xun beheaded the chanyu and took his head." },
  { zh: "得漢使節二及谷吉等所賫帛書。", literal: "They obtained two Han envoy staffs and the silk documents Gu Ji and others had been carrying.", idiomatic: "They recovered two Han envoy staffs and the silk documents Gu Ji and others had been carrying." },
  { zh: "諸鹵獲以畀得者。", literal: "The various booty seized was given to those who had obtained it.", idiomatic: "The various booty seized was given to those who had taken it." },
  { zh: "凡斬閼氏、太子、名王以下千五百一十八級；", literal: "In all they beheaded one thousand five hundred eighteen persons of the rank of yanzhi, crown prince, and noble king and below;", idiomatic: "In all they beheaded one thousand five hundred eighteen persons of the rank of consort, crown prince, noble king, and below;" },
  { zh: "生虜百四十五人，降虜千餘人，賦予城郭諸國所發十五王。", literal: "they took one hundred forty-five living captives and more than a thousand who surrendered; captives were distributed to the fifteen kings among the walled states that had mobilized.", idiomatic: "they took one hundred forty-five living captives and more than a thousand who surrendered; captives were distributed among the fifteen kings of the walled states that had mobilized." },
  { zh: "1春，正月，郅支首至京師。", literal: "1 In spring, the first month, Zhizhi's head reached the capital.", idiomatic: "1 In spring, the first month, Zhizhi's head reached the capital." },
  { zh: "延壽、湯上疏曰：「臣聞天下之大義當混為一，昔有唐、虞，今有強漢。", literal: "Yanshou and Tang submitted a memorial, saying: \"Your subjects have heard that the great meaning of All-under-Heaven ought to be unified as one; in antiquity there were Tang and Yu, and today there is mighty Han.", idiomatic: "Yanshou and Tang submitted a memorial, saying, \"Your subjects have heard that the great principle of All-under-Heaven ought to be unified as one; in antiquity there were Tang and Yu, and today there is mighty Han.\"" },
  { zh: "匈奴呼韓邪單于已稱北籓，唯郅支單于叛逆，未伏其辜，大夏之西，以為強漢不能臣也。", literal: "Among the Xiongnu, Chanyu Huhanye has already styled himself northern vassal; only Chanyu Zhizhi rebelled and has not submitted to his punishment; west of Great Xia they thought mighty Han could not make them subjects.", idiomatic: "Among the Xiongnu, Chanyu Huhanye has already styled himself a northern vassal; only Chanyu Zhizhi rebelled and has not submitted to punishment; west of the Tarim they thought mighty Han could not subdue them.\"" },
  { zh: "郅支單于慘毒行於民，大惡通於天。", literal: "Chanyu Zhizhi's cruel poison walked among the people; his great evil reached Heaven.", idiomatic: "Chanyu Zhizhi's cruelty walked among the people; his great evil reached Heaven.\"" },
  { zh: "臣延壽，臣湯，將義兵，行天誅，賴陛下神靈，陰陽並應，天氣精明，陷陳克敵，斬郅支首及名王以下，宜縣頭槁街蠻夷邸間，以示萬里，明犯強漢者，雖遠必誅！", literal: "Your subjects Yanshou and Tang led righteous troops and carried out Heaven's punishment; relying on Your Majesty's divine numen, yin and yang responded together, the weather was clear and bright, we stormed the ranks and overcame the enemy, and beheaded Zhizhi's head and those of noble kings and below—it is fitting to display the heads between Gao Street and the lodge for barbarians, to show it to ten thousand li: clearly, whoever offends mighty Han, though far away, will surely be punished!", idiomatic: "Your subjects Yanshou and Tang led righteous troops and carried out Heaven's punishment; relying on Your Majesty's divine favor, yin and yang responded together, the weather was clear and bright, we stormed the ranks and overcame the enemy, and beheaded Zhizhi and the noble kings below—it is fitting to display the heads between Gao Street and the lodge for barbarians, to show it ten thousand li away: whoever offends mighty Han, though far away, will surely be punished!\"" },
  { zh: "」丞相匡衡等以為：「方春，掩骼、埋胔之時，宜勿縣。", literal: "\" Chancellor Kuang Heng and others held: \"It is now spring, the season for covering bones and burying flesh—heads ought not to be displayed.", idiomatic: "\" Chancellor Kuang Heng and others argued, \"It is now spring, the season for covering bones and burying flesh—heads ought not to be displayed.\"" },
  { zh: "」詔縣十日，乃埋之。", literal: "\" An edict ordered them displayed for ten days, then buried.", idiomatic: "\" An edict ordered them displayed for ten days, then buried." },
  { zh: "仍告祠郊廟，赦天下。", literal: "He then announced the sacrifice at the suburban altars and ancestral temples and amnestied All-under-Heaven.", idiomatic: "He then announced sacrifices at the suburban altars and ancestral temples and amnestied All-under-Heaven." },
  { zh: "群臣上壽，置酒。", literal: "The multitude of ministers offered longevity wishes and wine was set out.", idiomatic: "The ministers offered congratulations and a feast was held." },
  { zh: "----2六月，甲申，中山哀王竟薨。", literal: "----2 In the sixth month, on day jiashen, Prince Ai of Zhongshan Jing died.", idiomatic: "----2 In the sixth month, on day jiashen, Prince Ai of Zhongshan Jing died." },
  { zh: "哀王者，帝之少弟，與太子遊學相長大。", literal: "Prince Ai was the emperor's younger brother; he and the heir apparent studied and traveled together and grew up together.", idiomatic: "Prince Ai was the emperor's younger brother; he and the heir apparent had studied together and grown up together." },
  { zh: "及薨，太子前吊。", literal: "When he died, the heir apparent went forward to offer condolences.", idiomatic: "When he died, the heir apparent went forward to offer condolences." },
  { zh: "上望見太子，感念哀王，悲不能自止。", literal: "The emperor, looking and seeing the heir apparent, was moved by thoughts of Prince Ai and grieved beyond stopping himself.", idiomatic: "The emperor, seeing the heir apparent, was moved by thoughts of Prince Ai and could not stop his grief." },
  { zh: "太子既至前，不哀，上大恨曰：「安有人不慈仁，而可以奉宗廟，為民父母者乎！", literal: "When the heir apparent had come before him and was not mournful, the emperor hated it greatly and said: \"How can there be a man without kindness and benevolence who may tend the ancestral temple and be father and mother to the people!", idiomatic: "When the heir apparent came before him without mourning, the emperor was greatly angered and said, \"How can there be a man without kindness and benevolence who may tend the ancestral temple and be father and mother to the people!\"" },
  { zh: "」是時駙馬都尉、侍中史丹護太子家，上以責謂丹，丹免冠謝曰：「臣誠見陛下哀痛中山王，至以感損。", literal: "\" At that time Chief Commandant of Escort Cavalry and Attendant within the Palace Shi Dan guarded the heir apparent's household; the emperor blamed and addressed Dan; Dan removed his cap and apologized, saying: \"Your subject truly saw Your Majesty's grief and pain for the king of Zhongshan, even to the point of being moved and harmed.", idiomatic: "\" At that time Chief Commandant of Escort Cavalry and Attendant within the Palace Shi Dan guarded the heir apparent's household; the emperor blamed him; Dan removed his cap and apologized, saying, \"Your subject truly saw Your Majesty's grief for the king of Zhongshan, even to the point of harming your health.\"" },
  { zh: "向者太子當進見，臣竊戒屬，毋涕泣，感傷陛下；", literal: "Earlier, when the heir apparent was about to advance to audience, your subject secretly warned and instructed him not to weep and sob, lest he move and harm Your Majesty;", idiomatic: "Earlier, when the heir apparent was about to come forward, your subject secretly warned him not to weep and sob, lest he add to Your Majesty's grief;\"" },
  { zh: "罪乃在臣，當死！", literal: "the crime lies in your subject—I ought to die!", idiomatic: "the fault lies with your subject—I ought to die!\"" },
  { zh: "」上以為然，意乃解。", literal: "\" The emperor thought it so and his mind was thereupon eased.", idiomatic: "\" The emperor accepted this and his anger eased." },
  { zh: "----3藍田地震，山崩，壅霸水；", literal: "----3 In Lantian there was an earthquake; mountains collapsed and blocked the Ba River;", idiomatic: "----3 In Lantian there was an earthquake; mountains collapsed and blocked the Ba River;" },
  { zh: "安陵岸崩，壅涇水，涇水逆流。", literal: "the banks at Anling collapsed, blocked the Jing River, and the Jing River flowed backward.", idiomatic: "the banks at Anling collapsed, blocked the Jing River, and the Jing River flowed backward." },
  { zh: "1春，三月，赦天下。", literal: "1 In spring, the third month, he amnestied All-under-Heaven.", idiomatic: "1 In spring, the third month, he amnestied All-under-Heaven." },
  { zh: "----2夏，六月，庚申，復戾園。", literal: "----2 In summer, the sixth month, on day gengshen, he restored Li Park.", idiomatic: "----2 In summer, the sixth month, on day gengshen, he restored Li Park." },
  { zh: "----3壬申晦，日有食之。", literal: "----3 On the last day of the month, day renshen, there was a solar eclipse.", idiomatic: "----3 On the last day of the month, day renshen, there was a solar eclipse." },
  { zh: "----4秋，七月，庚子，復太上皇寢廟園、原廟、-{昭靈后}-、武哀王、-{昭哀后}-、-{衛思后}-園。", literal: "----4 In autumn, the seventh month, on day gengzi, he restored the parks of the Grand Supreme Emperor's sleeping temple and ancestral shrine, the original temple, -{Empress Zhaoling}-, Prince Ai of Wu, -{Empress Zhaoi}-, and -{Empress Weisi}-.", idiomatic: "----4 In autumn, the seventh month, on day gengzi, he restored the parks of the Grand Supreme Emperor's sleeping temple and ancestral shrine, the original temple, -{Empress Zhaoling}-, Prince Ai of Wu, -{Empress Zhaoi}-, and -{Empress Weisi}-." },
  { zh: "時上寢疾，久不平。", literal: "At that time the emperor lay ill in bed and long was not restored.", idiomatic: "At that time the emperor lay ill and long failed to recover." },
  { zh: "以為祖宗譴怒，故盡復之；", literal: "He thought the ancestral temples had sent reproach and anger, and therefore restored them all;", idiomatic: "He thought the ancestral spirits had sent reproach and anger, and therefore restored them all;" },
  { zh: "唯郡國廟遂廢-{云}-。", literal: "only the temples of the commanderies and kingdoms were thereupon abolished -{yun}-.", idiomatic: "only the temples of the commanderies and kingdoms were thereupon abolished -{yun}-." },
  { zh: "----5是歲，徙濟陽王康為山陽王。", literal: "----5 That year, Prince Kang of Jiyang was moved and made Prince of Shanyang.", idiomatic: "----5 That year, Prince Kang of Jiyang was transferred and made Prince of Shanyang." },
  { zh: "----6匈奴呼韓邪單于聞郅支既誅，且喜且懼；", literal: "----6 When the Xiongnu Chanyu Huhanye heard Zhizhi had already been executed, he was both pleased and afraid;", idiomatic: "----6 When the Xiongnu chanyu Huhanye heard Zhizhi had already been executed, he was both pleased and afraid;" },
  { zh: "上書，願入朝見。", literal: "he submitted a memorial wishing to enter court for audience.", idiomatic: "he submitted a memorial wishing to come to court for audience." },
  { zh: "1春，正月，匈奴呼韓邪單于來朝，自言願婿漢氏以自親。", literal: "1 Spring, first month, the Xiongnu Chanyu Huhanye came to court, himself saying he wished to marry into the Han clan to draw close.", idiomatic: "1 In spring, the first month, the Xiongnu chanyu Huhanye came to court, saying he wished to marry into the Han house to draw closer." },
  { zh: "帝以後宮良家子王嬙字昭君賜單于。", literal: "The emperor took Wang Qiang, styled Zhaojun, a good-family daughter of the inner palace, and granted her to the chanyu.", idiomatic: "The emperor gave the chanyu Wang Qiang of the inner palace, a daughter of a good family, styled Zhaojun." },
  { zh: "單于歡喜，上書「願保塞上谷以西至敦煌，傳之無窮。", literal: "The chanyu rejoiced and submitted a memorial: \"I wish to guard the frontier from Shanggu westward to Dunhuang, transmitting this without end.", idiomatic: "The chanyu rejoiced and submitted a memorial: \"I wish to guard the frontier from Shanggu westward to Dunhuang and pass this down without end." },
  { zh: "請罷邊備塞吏卒，以休天子人民。", literal: "I request that frontier defenses and border garrison officers and soldiers be dismissed, to give rest to the Son of Heaven's people.", idiomatic: "I ask that frontier defenses and border garrison troops be dismissed, to give rest to the Son of Heaven's people." },
  { zh: "」天子下有司議，議者皆以為便。", literal: "\" The Son of Heaven sent it down to the relevant offices for deliberation; those who deliberated all considered it expedient.", idiomatic: "\" The emperor referred it to the relevant offices for deliberation; those who deliberated all considered it expedient." },
  { zh: "郎中侯應習邊事，以為不可許。", literal: "Gentleman-of-the-Palace Hou Ying, versed in frontier affairs, held that it could not be granted.", idiomatic: "Gentleman-of-the-Palace Hou Ying, versed in frontier affairs, held that it could not be granted." },
  { zh: "上問狀，應曰：「周、秦以來，匈奴暴桀，寇侵邊境；", literal: "The emperor asked the grounds; Ying said: \"From Zhou and Qin onward, the Xiongnu have been violent and fierce, raiding and encroaching on the borders;", idiomatic: "The emperor asked for his reasoning. Ying said, \"From Zhou and Qin onward the Xiongnu have been violent and fierce, raiding and encroaching on the borders;" },
  { zh: "漢興，尤被其害。", literal: "when Han arose, it especially suffered their harm.", idiomatic: "when Han arose, it especially suffered their harm." },
  { zh: "臣聞北邊塞至遼東，外有陰山，東西千餘里，草木茂盛，多禽獸，本冒頓單于依阻其中，治作弓矢，來出為寇，是其苑囿也。", literal: "Your subject has heard that from the northern frontier passes to Liaodong, beyond lies the Yin Mountains, more than a thousand li east and west, where grass and trees flourish and birds and beasts are many—originally Chanyu Modun relied on and blocked within them, making bows and arrows, coming forth to raid; it was his park and preserve.", idiomatic: "Your subject has heard that from the northern frontier passes to Liaodong, beyond lies the Yin Mountains, more than a thousand li east and west, where grass and trees flourish and birds and beasts abound. Chanyu Modun originally relied on them as a barrier, made bows and arrows there, and came forth to raid—it was his hunting park." },
  { zh: "至孝武世，出師征伐，斥奪此地，攘之於幕北，建塞徼，起亭隧，築外城，設屯戍以守之，然後邊境得用少安。", literal: "By the age of Emperor Xiaowu, troops were sent out to campaign and attack, driving out and seizing this land, thrusting them north of the desert; frontier defenses were built, beacon towers and signal posts raised, outer walls constructed, and garrison colonies set to guard them—only then could the borders obtain a little peace.", idiomatic: "By the reign of Emperor Wu, armies were sent out to campaign, this land was seized and the Xiongnu thrust north of the desert. Frontier defenses were built, beacon towers raised, outer walls constructed, and garrison colonies established to guard them—only then could the borders obtain a little peace." },
  { zh: "幕北地平，少草木，多大沙，匈奴來寇，少所蔽隱；", literal: "North of the desert the land is level, with little grass and trees and much great sand; when the Xiongnu come to raid, there is little by which to hide;", idiomatic: "North of the desert the land is level, with little grass and trees and much sand; when the Xiongnu come to raid, there is little cover;" },
  { zh: "從塞以南，逕深山谷，往來差難。", literal: "from south of the passes, the route runs through deep mountains and valleys, and coming and going is comparatively difficult.", idiomatic: "from south of the passes the route runs through deep mountains and valleys, and travel is comparatively difficult." },
  { zh: "邊長老言：『匈奴失陰山之後，過之未嘗不哭也。", literal: "Frontier elders say: 'After the Xiongnu lost the Yin Mountains, whenever they passed them they never failed to weep.", idiomatic: "Frontier elders say, \"After the Xiongnu lost the Yin Mountains, whenever they passed them they never failed to weep.\"" },
  { zh: "』如罷備塞戍卒，示夷狄之大利，不可一也。", literal: "' If frontier preparations and border garrison soldiers are dismissed, showing the great profit to the Yi and Di—this cannot be allowed, the first point.", idiomatic: "\" If frontier preparations and border garrisons are dismissed, showing the barbarians a great advantage—this cannot be allowed, the first point." },
  { zh: "今聖德廣被，天覆匈奴，匈奴得蒙全活之恩，稽首來臣。", literal: "Now sage virtue spreads broadly, Heaven covers the Xiongnu, and the Xiongnu have received the grace of full preservation and come bowing as subjects.", idiomatic: "Now sage virtue spreads broadly, Heaven covers the Xiongnu, and the Xiongnu have received the grace of preservation and come bowing as subjects." },
  { zh: "夫夷狄之情，困則卑順，強則驕逆，天性然也。", literal: "Now the temper of the Yi and Di: when pressed they are humble and compliant, when strong they are proud and rebellious—by nature it is so.", idiomatic: "The temper of the barbarians is that when pressed they are humble and compliant, when strong they are proud and rebellious—by nature it is so." },
  { zh: "前已罷外城，省亭隧，裁足以候望，通烽火而已。", literal: "Previously the outer walls were already dismissed and beacon towers reduced, barely enough for lookout and passing fire-signals alone.", idiomatic: "Previously the outer walls were already dismissed and beacon towers reduced, barely enough for lookout and passing fire-signals alone." },
  { zh: "古者安不忘危，不可復罷，二也。", literal: "In antiquity, in peace one did not forget danger—it cannot be dismissed again, the second point.", idiomatic: "In antiquity, in peace one did not forget danger—it cannot be dismissed again, the second point." },
  { zh: "中國有禮義之教，刑罰之誅，愚民猶尚犯禁；", literal: "The Central States have the teaching of ritual and righteousness and the execution of punishments, yet foolish common people still violate prohibitions;", idiomatic: "The Central States have the teaching of ritual and righteousness and the execution of punishments, yet foolish common people still violate prohibitions;" },
  { zh: "又況單于，能必其眾不犯約哉！", literal: "how much more the chanyu—can he surely make his masses not violate the agreement!", idiomatic: "how much more the chanyu—can he surely make his people keep the agreement!" },
  { zh: "三也。", literal: "The third point.", idiomatic: "The third point." },
  { zh: "自中國尚建關梁以制諸侯，所以絕臣下之覬欲也。", literal: "Even within the Central States passes and barriers are still built to control the feudal lords—this is to cut off the covetous desires of subjects below.", idiomatic: "Even within the Central States passes and barriers are built to control the feudal lords—to cut off the covetous desires of subjects below." },
  { zh: "設塞徼，置屯戍，非獨為匈奴而已，亦為諸屬國降民本故匈奴之人，恐其思舊逃亡，四也。", literal: "To set frontier defenses and place garrison colonies is not only for the Xiongnu alone; it is also because the surrendered peoples of the various dependent states were originally Xiongnu people, and one fears they will think of the old days and flee— the fourth point.", idiomatic: "Frontier defenses and garrison colonies are set not only for the Xiongnu alone, but also because the surrendered peoples of the dependent states were originally Xiongnu, and one fears they will think of the old days and flee—the fourth point." },
  { zh: "近西羌保塞，與漢人交通，吏民貪利，侵盜其畜產、妻子，以此怨恨，起而背畔。", literal: "Recently the Western Qiang guarded the passes and had dealings with Han people; officials and commoners, greedy for profit, encroached on and stole their livestock and wives and children; for this they bore resentment and rose in rebellion.", idiomatic: "Recently the Western Qiang guarded the passes and dealt with Han people; officials and commoners, greedy for profit, encroached on and stole their livestock and families; for this they bore resentment and rose in rebellion." },
  { zh: "今罷乘塞，則生嫚易分爭之漸，五也。", literal: "If garrisoning the passes is now dismissed, the beginning of contemptuous ease and mutual contention will arise—the fifth point.", idiomatic: "If garrisoning the passes is now dismissed, the beginning of contempt and strife will arise—the fifth point." },
  { zh: "往者從軍多沒不還者，子孫貧困，一旦亡出，從其親戚，六也。", literal: "In the past many who followed the army perished and did not return; their descendants are poor and pressed; in a single day they flee outward and follow their kin—the sixth point.", idiomatic: "In the past many who followed the army perished and did not return; their descendants are poor and pressed; in a single day they flee outward to join their kin—the sixth point." },
  { zh: "又邊人奴婢愁苦，欲亡者多，曰：『聞匈奴中樂，無奈候望急何！", literal: "Moreover border people's slaves and servants are bitter and distressed; many wish to flee, saying: 'We hear that life among the Xiongnu is pleasant—what can we do about the urgent lookout duties!", idiomatic: "Moreover border people's slaves and servants are bitter and distressed; many wish to flee, saying, \"We hear that life among the Xiongnu is pleasant—what can we do about the urgent lookout duties!\"" },
  { zh: "』然時有亡出塞者，七也。", literal: "' Yet from time to time there are those who flee out beyond the passes—the seventh point.", idiomatic: "\" Yet from time to time there are those who flee out beyond the passes—the seventh point." },
  { zh: "盜賊桀黠，群輩犯法，如其窘急，亡走北出，則不可制，八也。", literal: "Robbers and bandits are fierce and cunning; in groups they violate the law; if pressed to extremity they flee northward out of the passes and cannot be controlled—the eighth point.", idiomatic: "Robbers and bandits are fierce and cunning; in groups they violate the law; if pressed to extremity they flee northward beyond the passes and cannot be controlled—the eighth point." },
  { zh: "起塞以來百有餘年，非皆以土垣也，或因山巖、石、木、溪谷、水門，稍稍平之，卒徒築治，功費久遠，不可勝計。", literal: "Since frontier defenses were raised, more than a hundred years have passed; they were not all earthen walls—some followed mountain crags, stone, timber, ravines, valleys, and water gates, gradually leveled; corvée laborers built and repaired them; the labor and expense extend far back and cannot be fully reckoned.", idiomatic: "Since frontier defenses were raised, more than a hundred years have passed. They were not all earthen walls—some followed mountain crags, stone, timber, ravines, valleys, and water gates and were gradually improved. Corvée laborers built and repaired them at cost extending far back beyond reckoning." },
  { zh: "臣恐議者不深慮其終始，欲以壹切省繇戍，十年之外，百歲之內，卒有它變，障塞破壞，亭隧滅絕，當更發屯繕治，累世之功不可卒復，九也。", literal: "Your subject fears the deliberators do not deeply consider beginning and end, wishing to dismiss corvée and garrison all at once; within ten years or within a hundred years, if suddenly there is another change, barrier passes will be broken, beacon towers extinguished, and when garrisons must again be raised and repairs made, the achievements of successive generations cannot be suddenly restored—the ninth point.", idiomatic: "Your subject fears the deliberators do not deeply consider beginning and end and wish to dismiss corvée and garrison all at once. Within ten years or a hundred years, if suddenly there is another change, barrier passes will be broken and beacon towers destroyed. When garrisons must again be raised and repairs made, the achievements of successive generations cannot be suddenly restored—the ninth point." },
  { zh: "如罷戍卒，省候望，單于自以保塞守禦，必深德漢，請求無已；", literal: "If garrison soldiers are dismissed and lookout reduced, the chanyu, thinking himself able to guard the passes and defend, will surely feel deep gratitude toward Han and his requests will have no end;", idiomatic: "If garrison soldiers are dismissed and lookout reduced, the chanyu, thinking himself able to guard the passes and defend, will surely feel deep gratitude toward Han and his requests will have no end;" },
  { zh: "小失其意，則不可測。", literal: "if his intent is slightly disappointed, then the outcome cannot be foreseen.", idiomatic: "if his intent is slightly disappointed, the outcome cannot be foreseen." },
  { zh: "開夷狄之隙，虧中國之固，十也。", literal: "Opening a rift with the Yi and Di and impairing the solidity of the Central States—the tenth point.", idiomatic: "Opening a rift with the barbarians and impairing the solidity of the Central States—the tenth point." },
  { zh: "非所以永持至安，威制百蠻之長策也！", literal: "This is not the long-range policy by which to forever maintain utmost peace and awe and control the hundred barbarians!", idiomatic: "This is not the long-range policy by which to forever maintain utmost peace and awe and control the hundred barbarians!\"" },
  { zh: "」對奏，天子有詔：「勿議罷邊塞事。", literal: "\" When the reply was submitted, the Son of Heaven issued an edict: \"Do not deliberate further on dismissing frontier defenses.", idiomatic: "\" When the reply was submitted, the emperor issued an edict: \"Do not deliberate further on dismissing frontier defenses.\"" },
  { zh: "」使車騎將軍嘉口諭單于曰：「單于上書願罷北塞吏士屯戍，子孫世世保塞。", literal: "\" He sent General of Chariots and Cavalry Jia to instruct the chanyu orally, saying: \"The chanyu in his memorial wished to dismiss northern frontier officers and soldiers and garrison colonies, with descendants guarding the passes generation after generation.", idiomatic: "\" He sent General of Chariots and Cavalry Jia to instruct the chanyu orally, saying, \"In your memorial you wished to dismiss northern frontier officers, soldiers, and garrisons, with descendants guarding the passes generation after generation.\"" },
  { zh: "單于鄉慕禮義，所以為民計者甚厚。", literal: "The chanyu admires and yearns for ritual and righteousness; what he plans for his people is very generous.", idiomatic: "The chanyu admires ritual and righteousness; what you plan for your people is very generous." },
  { zh: "此長久之策也，朕甚嘉之。", literal: "This is a long-lasting policy, and We greatly commend it.", idiomatic: "This is a long-lasting policy, and We greatly commend it." },
  { zh: "中國四方皆有關梁障塞，非獨以備塞外也，亦以防中國奸邪放縱，出為寇害，故明法度以專眾心也。", literal: "The Central States on all four sides have passes, barriers, and frontier defenses—not only to prepare against those beyond the passes, but also to guard against the wicked and unrestrained within the Central States who go forth as raiders and harm; therefore laws and standards are made clear to focus the hearts of the masses.", idiomatic: "The Central States on all four sides have passes, barriers, and frontier defenses—not only to guard against those beyond the passes, but also to guard against the wicked and unrestrained within who go forth as raiders and harm. Therefore laws and standards are made clear to focus the hearts of the people." },
  { zh: "敬諭單于之意，朕無疑焉。", literal: "Respectfully We have made clear the chanyu's intent; We have no doubts.", idiomatic: "We have respectfully made your intent clear; We have no doubts." },
  { zh: "為單于怪其不罷，故使嘉曉單于。", literal: "Because the chanyu wondered that they were not dismissed, We therefore sent Jia to make it clear to the chanyu.", idiomatic: "Because you wondered that they were not dismissed, We therefore sent Jia to explain to you.\"" },
  { zh: "」單于謝曰：「愚不知大計，天子幸使大臣告語，甚厚！", literal: "\" The chanyu apologized, saying: \"Foolishly I did not know the great plan; the Son of Heaven was gracious to send a great minister to inform me—very generous!", idiomatic: "\" The chanyu apologized, saying, \"Foolishly I did not know the great plan. The Son of Heaven was gracious to send a great minister to inform me—very generous!" },
  { zh: "初，左伊秩訾為呼韓邪畫計歸漢，竟以安定。", literal: "Earlier, the Left Wise King Yizhizi had devised the plan for Huhanye to return to Han, and in the end stability was achieved.", idiomatic: "Earlier the Left Wise King Yizhizi had devised the plan for Huhanye to return to Han, and in the end stability was achieved." },
  { zh: "其後或讒伊秩訾自伐其功，常鞅鞅，呼韓邪疑之；", literal: "Afterward some slandered Yizhizi for boasting of his achievement; he was often discontented, and Huhanye came to doubt him;", idiomatic: "Afterward some slandered Yizhizi for boasting of his achievement; he was often discontented, and Huhanye came to doubt him;" },
  { zh: "伊秩訾懼誅，將其眾千餘人降漢，漢以為關內侯，食邑三百戶，令佩其王印綬。", literal: "Yizhizi, fearing execution, led his masses of more than a thousand men to surrender to Han; Han made him Marquis within the Passes, with a fief of three hundred households, and ordered him to wear his royal seal and ribbon.", idiomatic: "Yizhizi, fearing execution, led his following of more than a thousand men to surrender to Han. Han made him Marquis within the Passes, with a fief of three hundred households, and ordered him to wear his royal seal and ribbon." },
  { zh: "及呼韓邪來朝，與伊秩訾相見，謝曰：「王為我計甚厚，令匈奴至今安寧，王之力也，德豈可忘！", literal: "When Huhanye came to court and met Yizhizi, he apologized, saying: \"Your Highness planned for me very generously, causing the Xiongnu down to today to be peaceful and secure—it is Your Highness's power; how could the grace be forgotten!", idiomatic: "When Huhanye came to court and met Yizhizi, he apologized, saying, \"Your Highness planned for me very generously and caused the Xiongnu down to today to be peaceful and secure—it is your doing. How could that grace be forgotten!\"" },
  { zh: "我失王意，使王去，不復顧留，皆我過也。", literal: "I lost Your Highness's intent and made Your Highness leave, no longer looking back to stay—all is my fault.", idiomatic: "I lost your favor and made you leave, no longer looking back to stay—all is my fault." },
  { zh: "今欲白天子，請王歸庭。", literal: "Now I wish to inform the Son of Heaven and ask Your Highness to return to the court.", idiomatic: "Now I wish to inform the Son of Heaven and ask you to return to the court.\"" },
  { zh: "」伊秩訾曰：「單于賴天命，自歸於漢，得以安寧，單于神靈，天子之祐也，我安得力！", literal: "\" Yizhizi said: \"The chanyu relied on Heaven's mandate and returned of himself to Han, and so obtained peace and security—it is the chanyu's spirit and the Son of Heaven's protection; how could I have had power!", idiomatic: "\" Yizhizi said, \"The chanyu relied on Heaven's mandate and returned of himself to Han and so obtained peace and security—it is the chanyu's spirit and the Son of Heaven's protection. How could I have had any power!\"" },
  { zh: "既已降漢，又復歸匈奴，是兩心也。", literal: "Having already surrendered to Han, to return again to the Xiongnu would be having two hearts.", idiomatic: "Having already surrendered to Han, to return again to the Xiongnu would be having two hearts." },
  { zh: "願為單于侍使於漢，不敢聽命！", literal: "I wish to serve the chanyu as envoy at Han and dare not obey the command!", idiomatic: "I wish to serve you as envoy at Han and dare not obey the command!\"" },
  { zh: "」單于固請，不能得而歸。", literal: "\" The chanyu firmly pressed the request but could not obtain him and so returned.", idiomatic: "\" The chanyu firmly pressed the request but could not obtain him and returned." },
  { zh: "單于號王昭君為寧胡閼氏；", literal: "The chanyu styled Wang Zhaojun Ninghu Yanzhi;", idiomatic: "The chanyu styled Wang Zhaojun Peaceful-Hu Imperial Consort;" },
  { zh: "生一男伊屠智牙師，為右日逐王。", literal: "she bore a son, Yitu Zhiyashi, who was made Right Commander in Chief of the Sun.", idiomatic: "she bore a son, Yitu Zhiyashi, who was made Right Commander in Chief of the Sun." },
  { zh: "----2皇太子冠。", literal: "----2 The heir apparent received the capping ceremony.", idiomatic: "----2 The heir apparent received the capping ceremony." },
  { zh: "----3二月，御史大夫李延壽卒。", literal: "----3 Second month, Censor-in-Chief Li Yanshou died.", idiomatic: "----3 In the second month, Censor-in-Chief Li Yanshou died." },
  { zh: "----4初，石顯見馮奉世父子為公卿著名，女又為昭儀在內，顯心欲附之，薦言：「昭儀兄謁者逡修敕，宜侍幄帷。", literal: "----4 Earlier, Shi Xian saw Feng Fengshi and his son famed as high ministers, and the daughter also serving as Brilliant Companion within; Xian's heart wished to attach to them and recommended, saying: \"The Brilliant Companion's elder brother, Palace Attendant Jun, is cultivated and orderly and ought to attend within the curtains.", idiomatic: "----4 Earlier Shi Xian saw Feng Fengshi and his son famed as high ministers, with the daughter also serving as Brilliant Companion within. Xian wished to attach himself to them and recommended, saying, \"The Brilliant Companion's elder brother, Palace Attendant Jun, is cultivated and orderly and ought to attend within the curtains.\"" },
  { zh: "」天子召見，欲以為侍中。", literal: "\" The Son of Heaven summoned and saw him, wishing to make him Palace Attendant.", idiomatic: "\" The emperor summoned and saw him, wishing to make him Palace Attendant." },
  { zh: "逡請間言事。", literal: "Jun requested a private audience to speak on affairs.", idiomatic: "Jun requested a private audience to speak on affairs." },
  { zh: "上聞逡言顯專權，大怒，罷逡歸郎官。", literal: "The emperor heard Jun say Xian monopolized power, was greatly angered, dismissed Jun, and returned him to Gentleman-of-the-Palace.", idiomatic: "The emperor heard Jun say Xian monopolized power, was greatly angered, dismissed Jun, and returned him to Gentleman-of-the-Palace." },
  { zh: "及御史大夫缺，在位多舉逡兄大鴻臚野王；", literal: "When the censor-in-chief's post was vacant, those in office mostly recommended Jun's elder brother, Grand Herald Yewang;", idiomatic: "When the censor-in-chief's post was vacant, those in office mostly recommended Jun's elder brother, Grand Herald Yewang;" },
  { zh: "上使尚書選第中二千石，而野王行能第一。", literal: "the emperor ordered the Masters of Writing to select and rank those at two thousand bushels and above, and Yewang's conduct and ability ranked first.", idiomatic: "the emperor ordered the Masters of Writing to select and rank those at two thousand bushels and above, and Yewang's conduct and ability ranked first." },
  { zh: "上以問顯，顯曰：「九卿無出野王者。", literal: "The emperor questioned Xian; Xian said: \"Among the nine ministers none surpasses Yewang.", idiomatic: "The emperor questioned Xian. Xian said, \"Among the nine ministers none surpasses Yewang." },
  { zh: "然野王，親昭儀兄，臣恐後世必以陛下度越眾賢，私後宮親以為三公。", literal: "Yet Yewang is the Brilliant Companion's elder brother; your subject fears later ages will surely say Your Majesty overstepped the many worthies and privately favored inner-palace kin to make one Grand Mentor of State.", idiomatic: "Yet Yewang is the Brilliant Companion's elder brother. Your subject fears later ages will say Your Majesty overstepped the many worthies and privately favored inner-palace kin to make one chancellor.\"" },
  { zh: "」上曰：「善，吾不見是！", literal: "\" The emperor said: \"Good—I did not see this!", idiomatic: "\" The emperor said, \"Good—I did not see this!\"" },
  { zh: "」因謂群臣曰：「吾用野王為三公，後世必謂我私後宮親屬，以野王為比。", literal: "\" He thereupon said to the assembled ministers: \"If I used Yewang as Grand Mentor of State, later ages would surely say I favored inner-palace kin, taking Yewang as the comparison.", idiomatic: "\" He thereupon said to the assembled ministers, \"If I used Yewang as chancellor, later ages would surely say I favored inner-palace kin, taking Yewang as the comparison.\"" },
  { zh: "」三月，丙寅，詔曰：「剛強堅固，確然亡欲，大鴻臚野王是也。", literal: "\" Third month, on bingyin, an edict said: \"Firm, strong, solid, and fixed, clearly without desire—Grand Herald Yewang is such.", idiomatic: "\" In the third month, on bingyin, an edict said, \"Firm, strong, solid, and fixed, clearly without desire—Grand Herald Yewang is such." },
  { zh: "心辨善辭，可使四方，少府五鹿充宗是也。", literal: "His heart discriminates and he is skilled in speech, fit to be sent to the four quarters—Minister Steward Wulu Chongzong is such.", idiomatic: "His heart discriminates and he is skilled in speech, fit to be sent to the four quarters—Minister Steward Wulu Chongzong is such." },
  { zh: "廉潔節儉，太子少傅張譚是也。", literal: "Pure, clean, and frugal—Junior Tutor of the Heir Apparent Zhang Tan is such.", idiomatic: "Pure, clean, and frugal—Junior Tutor of the Heir Apparent Zhang Tan is such." },
  { zh: "其以少傅為御史大夫。", literal: "Let the Junior Tutor be made censor-in-chief.", idiomatic: "Let the Junior Tutor be made censor-in-chief.\"" },
  { zh: "」----5河南太守九江召信臣為少府。", literal: "\" ----5 Administrator of Henan Zhao Xinchen of Jiujiang was made Minister Steward.", idiomatic: "\" ----5 Administrator of Henan Zhao Xinchen of Jiujiang was made Minister Steward." },
  { zh: "信臣先為南陽太守，後遷河南，治行常第一。", literal: "Xinchen had first been Administrator of Nanyang, afterward transferred to Henan; his governance and conduct were constantly first.", idiomatic: "Xinchen had first been Administrator of Nanyang, then transferred to Henan; his governance and conduct were constantly first." },
  { zh: "視民如子，好為民興利，躬勸耕稼，開通溝瀆，戶口增倍。", literal: "He regarded the people as children, delighted in creating benefit for the people, personally encouraged plowing and sowing, opened and connected ditches and channels, and household registers doubled.", idiomatic: "He regarded the people as children, delighted in creating benefit for them, personally encouraged plowing and sowing, opened ditches and channels, and household registers doubled." },
  { zh: "吏民親愛，號曰「召父」。", literal: "Officials and people loved him and called him \"Father Zhao.\"", idiomatic: "Officials and people loved him and called him \"Father Zhao.\"" },
  { zh: "----6癸未，復孝惠皇帝寢廟園、孝文太后、孝昭太后寢園。", literal: "----6 On guiwei, the park temples of Emperor Xiaohui, Empress Dowager Xiaowen, and Empress Dowager Xiaozhao were restored.", idiomatic: "----6 On guiwei, the park temples of Emperor Xiaohui, Empress Dowager Xiaowen, and Empress Dowager Xiaozhao were restored." },
  { zh: "----7初，中書令石顯嘗欲以姊妻甘延壽，延壽不取。", literal: "----7 Earlier, Director of the Palace Secretariat Shi Xian had wished to marry his elder sister to Gan Yanshou; Yanshou did not take her.", idiomatic: "----7 Earlier Director of the Palace Secretariat Shi Xian had wished to marry his elder sister to Gan Yanshou; Yanshou refused." },
  { zh: "及破郅支還，丞相、御史亦惡其矯制，皆不與延壽等。", literal: "When they returned after defeating Zhizhi, the chancellor and censor-in-chief also hated their usurpation of authority and all treated Yanshou as an equal.", idiomatic: "When they returned after defeating Zhizhi, the chancellor and censor-in-chief also hated their unauthorized campaign and would not treat Yanshou as an equal." },
  { zh: "陳湯素貪，所鹵獲財物入塞，多不法。", literal: "Chen Tang was by nature greedy; goods plundered and brought within the passes were mostly unlawful.", idiomatic: "Chen Tang was by nature greedy; plundered goods brought within the passes were mostly unlawful." },
  { zh: "司隸校尉移書道上，系吏士，按驗之。", literal: "The Director of Convict Labor sent documents on the road, seized officers and soldiers, and investigated and verified them.", idiomatic: "The Director of Convict Labor sent documents along the road, seized officers and soldiers, and investigated them." },
  { zh: "湯上疏言：「臣與吏士共誅郅支單于，幸得禽滅，萬里振旅，宜有使者迎勞道路。", literal: "Tang submitted a memorial saying: \"Your subject together with officers and soldiers jointly executed Chanyu Zhizhi; by fortune he was captured and destroyed; the army was shaken for ten thousand li—there ought to be envoys to welcome and comfort them on the road.", idiomatic: "Tang submitted a memorial saying, \"Your subject together with officers and soldiers executed Chanyu Zhizhi; by fortune he was captured and destroyed. The army was shaken for ten thousand li—there ought to be envoys to welcome and comfort them on the road." },
  { zh: "今司隸反逆收系按驗，是為郅支報讎也！", literal: "Now the Director of Convict Labor perversely seizes, binds, and investigates and verifies them—this is taking revenge for Zhizhi!", idiomatic: "Now the Director of Convict Labor perversely seizes and investigates them—this is taking revenge for Zhizhi!\"" },
  { zh: "」上立出吏士，令縣、道出酒食以過軍。", literal: "\" The emperor at once released the officers and soldiers and ordered counties and commanderies along the route to provide wine and food as the army passed.", idiomatic: "\" The emperor at once released the officers and soldiers and ordered counties and commanderies along the route to provide wine and food as the army passed." },
  { zh: "既至，論功，石顯、匡衡以為：「延壽、湯擅興師矯制，幸得不誅，如復加爵土，則後奉使者爭欲乘危徼幸，生事於蠻夷，為國招難。", literal: "When they arrived, merits were discussed; Shi Xian and Kuang Heng held: \"Yanshou and Tang on their own authority raised troops and usurped command; by fortune they were not executed—if rank and fief are again added, then later envoys sent on missions will all contend to seize danger and seek fortune, creating affairs among the barbarians and bringing trouble to the state.", idiomatic: "When they arrived, merits were discussed. Shi Xian and Kuang Heng argued, \"Yanshou and Tang on their own authority raised troops and usurped command; by fortune they were not executed. If rank and fief are again added, later envoys will all contend to seize danger and seek fortune, create affairs among the barbarians, and bring trouble to the state.\"" },
  { zh: "」帝內嘉延壽、湯功而重違衡、顯之議，久之不決。", literal: "\" The emperor inwardly commended Yanshou and Tang's achievement yet heavily weighed going against Heng and Xian's deliberation; for a long time he did not decide.", idiomatic: "\" The emperor inwardly commended Yanshou and Tang's achievement yet heavily weighed going against Heng and Xian's view; for a long time he did not decide." },
  { zh: "故宗正劉向上疏曰：「郅支單于囚殺使者、吏士以百數，事暴揚外國，傷威毀重，群臣皆閔焉。", literal: "Former Director of the Imperial Clan Liu Xiang submitted a memorial saying: \"Chanyu Zhizhi imprisoned and killed envoys and officers and soldiers by the hundreds; the affair was openly displayed to foreign states, injuring prestige and destroying weight; the assembled ministers all pitied it.", idiomatic: "Former Director of the Imperial Clan Liu Xiang submitted a memorial saying, \"Chanyu Zhizhi imprisoned and killed envoys and officers and soldiers by the hundreds. The affair was openly displayed to foreign states, injuring prestige and authority. The assembled ministers all lamented it." },
  { zh: "陛下赫然欲誅之，意未嘗有忘。", literal: "Your Majesty was suddenly aroused and wished to execute him; the intent was never forgotten.", idiomatic: "Your Majesty was suddenly aroused and wished to execute him; the intent was never forgotten." },
  { zh: "西域都護延壽，副校尉湯，承聖指，倚神靈，總百蠻之君，攬城郭之兵，出百死，入絕域，遂蹈康居，屠三重城，搴歙侯之旗，斬郅支之首，縣旌萬里之外，揚威昆山之西，掃谷吉之恥，立昭明之功，萬夷懾伏，莫不懼震。", literal: "Protector of the Western Regions Yanshou and Vice Commandant Tang, receiving the sage directive and relying on spiritual power, gathered the lords of the hundred barbarians and drew in walled-city troops, went out through a hundred deaths and entered cut-off regions, then trod Kangju, slaughtered the triple-walled city, pulled down the banner of the Xiuhou, cut off Zhizhi's head, hung the pennant ten thousand li beyond, displayed might west of Kunlun, swept away Gu Ji's shame, and established brilliant manifest achievement; the myriad Yi were awed and submitted, none not fearing and trembling.", idiomatic: "Protector of the Western Regions Yanshou and Vice Commandant Tang, receiving the sage directive and relying on spiritual power, gathered the lords of the hundred barbarians and drew in walled-city troops, went out through a hundred deaths and entered cut-off regions, trod Kangju, slaughtered the triple-walled city, pulled down the Xiuhou's banner, cut off Zhizhi's head, hung the pennant ten thousand li beyond, displayed might west of Kunlun, swept away Gu Ji's shame, and established brilliant manifest achievement. The myriad barbarians were awed and submitted; none failed to fear and tremble." },
  { zh: "呼韓邪單于見郅支已誅，且喜且懼，鄉風馳義，稽首來賓，願守北籓，累世稱臣。", literal: "Chanyu Huhanye, seeing Zhizhi already executed, was both pleased and afraid; he turned toward the wind and rushed in righteousness, bowed his head and came as guest, wishing to guard the northern藩 and be called subject for successive generations.", idiomatic: "Chanyu Huhanye, seeing Zhizhi already executed, was both pleased and afraid. He turned toward the wind and rushed in righteousness, bowed his head and came as guest, wishing to guard the northern frontier and be called subject for successive generations." },
  { zh: "立千載之功，建萬世之安，群臣之勳莫大焉。", literal: "To establish achievement for a thousand ages and build security for ten thousand generations—the ministers' merit could not be greater.", idiomatic: "To establish achievement for a thousand ages and build security for ten thousand generations—the ministers' merit could not be greater." },
  { zh: "昔周大夫方叔、吉甫為宣王誅獫狁而百蠻從，其詩曰：『嘽嘽焞焞，如霆如雷。", literal: "Formerly Zhou grandees Fang Shu and Jifu for King Xuan executed the Xianyun and the hundred barbarians followed; the ode says: 'Tun tun, hui hui, like thunderbolt and like thunder.", idiomatic: "Formerly Zhou grandees Fang Shu and Jifu for King Xuan executed the Xianyun and the hundred barbarians followed. The ode says, \"Tun tun, hui hui, like thunderbolt and like thunder.\"" },
  { zh: "顯允方叔，征伐獫狁，蠻荊來威。", literal: "Manifest and true is Fang Shu; campaigning against the Xianyun, the Man and Jing came to show awe.", idiomatic: "\"Manifest and true is Fang Shu; campaigning against the Xianyun, the Man and Jing came to show awe.\"" },
  { zh: "』《易》曰：『有嘉折首，獲匪其醜。", literal: "' The Changes says: 'There is praise in cutting off heads; what is captured is not their ugly masses.", idiomatic: "\" The Changes says, \"There is praise in cutting off heads; what is captured is not their ugly masses.\"" },
  { zh: "』言美誅首惡之人，而諸不順者皆來從也。", literal: "' It means it is praiseworthy to execute the chief evil man, and all who were not compliant come to follow.", idiomatic: "\" It means it is praiseworthy to execute the chief evil man, and all who were not compliant come to follow." },
  { zh: "今延壽、湯所誅震，雖《易》之折首，《詩》之雷霆，不能及也。", literal: "Now the shock of what Yanshou and Tang executed—even the Changes' cutting off heads and the Odes' thunderbolt and thunder—cannot reach it.", idiomatic: "Now the shock of what Yanshou and Tang executed—even the Changes' cutting off heads and the Odes' thunderbolt and thunder—cannot match it." },
  { zh: "論大功者不錄小過，舉大美者不疵細瑕。", literal: "When discussing great achievement one does not record small faults; when raising up great beauty one does not pick at fine flaws.", idiomatic: "When discussing great achievement one does not record small faults; when raising up great beauty one does not pick at fine flaws." },
  { zh: "《司馬法》曰：『軍賞不逾月，』欲民速得為善之利也。", literal: "The Methods of Sima says: 'Military rewards do not pass beyond the month,' wishing the people quickly to obtain the profit of doing good.", idiomatic: "The Methods of Sima says, \"Military rewards do not pass beyond the month,\" wishing the people quickly to obtain the profit of doing good." },
  { zh: "蓋急武功，重用人也。", literal: "This is probably to hurry military achievement and heavily employ men.", idiomatic: "This is to hurry military achievement and heavily employ men." },
  { zh: "吉甫之歸，周厚賜之，其詩曰：『吉甫燕喜，既多受祉。", literal: "When Jifu returned, Zhou richly rewarded him; the ode says: 'Jifu feasts in joy, having already received many blessings.", idiomatic: "When Jifu returned, Zhou richly rewarded him. The ode says, \"Jifu feasts in joy, having already received many blessings.\"" },
  { zh: "來歸自鎬，我行永久。", literal: "Coming back from Hao, my journey is long-lasting.", idiomatic: "Coming back from Hao, my journey is long-lasting.\"" },
  { zh: "』千里之鎬猶以為遠，況萬里之外，其勤至矣。", literal: "' A thousand li to Hao is still considered far—how much more ten thousand li beyond; his diligence reached the utmost.", idiomatic: "\" A thousand li to Hao is still considered far—how much more ten thousand li beyond; his diligence reached the utmost.\"" },
  { zh: "延壽、湯既未獲受祉之報，反屈捐命之功，久挫於刀筆之前，非所以勸有功，厲戎士也。", literal: "Yanshou and Tang, having not yet received the reward of blessings, instead had their life-risking achievement bent low, long thwarted before the writing brush—this is not the way to encourage those with achievement and spur martial officers.", idiomatic: "Yanshou and Tang, having not yet received the reward of blessings, instead had their life-risking achievement bent low and long thwarted before the writing brush—this is not the way to encourage merit and spur martial officers." },
  { zh: "昔齊桓前有尊周之功，後有滅項之罪，君子以功覆過而為之諱。", literal: "Of old Duke Huan of Qi first had the achievement of honoring Zhou, afterward the crime of destroying Xiang; the gentleman, taking achievement to cover faults, made excuse for him.", idiomatic: "Of old Duke Huan of Qi first had the achievement of honoring Zhou, afterward the crime of destroying Xiang; the gentleman, taking achievement to cover faults, made excuse for him." },
  { zh: "貳師將軍李廣利，捐五萬之師，靡億萬之費，經四年之勞，而僅獲駿馬三十匹，雖斬宛王母寡之首，猶不足以復費，其私罪惡甚多；", literal: "General Ershi Li Guangli expended an army of fifty thousand and consumed hundreds of millions in expense, through four years of toil, and obtained only thirty fine horses; though he cut off the head of the Queen Mother of Dayuan, Gua Mu, it still did not suffice to repay the cost, and his private crimes and evils were very many;", idiomatic: "General Ershi Li Guangli expended an army of fifty thousand and hundreds of millions in expense, through four years of toil, and obtained only thirty fine horses; though he cut off the head of the Queen Mother of Dayuan, Gua Mu, it still did not repay the cost, and his private crimes and evils were very many;" },
  { zh: "孝武以為萬里征伐，不錄其過，遂封拜兩侯、三卿、二千石百有餘人。", literal: "Emperor Xiaowu, thinking it a campaign of ten thousand li, did not record his faults, and thereupon enfeoffed and promoted two marquises, three ministers, and more than a hundred men at two thousand bushels.", idiomatic: "Emperor Wu, thinking it a campaign of ten thousand li, did not record his faults, and thereupon enfeoffed and promoted two marquises, three ministers, and more than a hundred men at two thousand bushels." },
  { zh: "今康居之國，強於大宛，郅支之號，重於宛王，殺使者罪，甚於留馬，而延壽、湯不煩漢士，不費斗糧，比於貳師，功德百之。", literal: "Now the state of Kangju is stronger than Dayuan, Zhizhi's title heavier than the King of Dayuan, the crime of killing envoys greater than detaining horses—yet Yanshou and Tang did not trouble Han soldiers or spend a peck of grain; compared with Ershi, their merit and virtue are a hundredfold.", idiomatic: "Now the state of Kangju is stronger than Dayuan, Zhizhi's title heavier than the King of Dayuan, the crime of killing envoys greater than detaining horses—yet Yanshou and Tang did not trouble Han soldiers or spend a peck of grain; compared with Ershi, their merit and virtue are a hundredfold." },
  { zh: "且常惠隨欲擊之烏孫，鄭吉迎自來之日逐，猶皆裂土受爵。", literal: "Moreover Chang Hui, following the Wusun in attacking them as they wished, and Zheng Ji welcoming the Riji themselves—both still received fiefs and titles.", idiomatic: "Moreover Chang Hui, following the Wusun in attacking them as they wished, and Zheng Ji welcoming the Riji themselves—both still received fiefs and titles." },
  { zh: "故言威武勤勞，則大於方叔、吉甫；", literal: "Thus in speaking of martial awe and diligent toil, they are greater than Fang Shu and Jifu;", idiomatic: "Thus in speaking of martial awe and diligent toil, they are greater than Fang Shu and Jifu;" },
  { zh: "列功覆過，則優於齊桓、貳師；", literal: "in ranking achievement to cover faults, they surpass Duke Huan of Qi and Ershi;", idiomatic: "in ranking achievement to cover faults, they surpass Duke Huan of Qi and Ershi;" },
  { zh: "近事之功，則高於安遠、長羅。", literal: "in recent achievements, they are higher than An Yuan and Chang Luo.", idiomatic: "in recent achievements, they are higher than An Yuan and Chang Luo." },
  { zh: "而大功未著，小惡數布，臣竊痛之！", literal: "Yet great achievement is not displayed while small faults are repeatedly spread abroad—your subject privately grieves at this!", idiomatic: "Yet great achievement is not displayed while small faults are repeatedly spread abroad—your subject privately grieves at this!" },
  { zh: "宜以時解縣，通籍，除過勿治，尊寵爵位，以勸有功。", literal: "They ought in timely fashion to be released from suspension, entered on the registers, absolved of faults and not prosecuted, honored with noble rank, to encourage those with achievement.", idiomatic: "They ought in timely fashion to be released from suspension, entered on the registers, absolved of faults and not prosecuted, and honored with noble rank to encourage merit." },
  { zh: "於是天子下詔赦延壽、湯罪勿治，令公卿議封焉。", literal: "Thereupon the Son of Heaven issued an edict pardoning Yanshou and Tang, their crimes not to be prosecuted, and ordered the high ministers to deliberate on enfeoffment.", idiomatic: "Thereupon the emperor issued an edict pardoning Yanshou and Tang, their crimes not to be prosecuted, and ordered the high ministers to deliberate on enfeoffment." },
  { zh: "議者以為宜如軍法捕斬單于令。", literal: "Those who deliberated held that it should follow the military law's ordinance for capturing and beheading the chanyu.", idiomatic: "Those who deliberated held that it should follow the military law's ordinance for capturing and beheading the chanyu." },
  { zh: "匡衡、石顯以為「郅支本亡逃失國，竊號絕域，非真單于。", literal: "Kuang Heng and Shi Xian held that \"Zhizhi had originally fled in exile and lost his state, usurping a title in the far frontier—not a true chanyu.", idiomatic: "Kuang Heng and Shi Xian held that \"Zhizhi had originally fled in exile and lost his state, usurping a title in the far frontier—not a true chanyu." },
  { zh: "」帝取安遠侯鄭吉故事，封千戶；", literal: "\" The emperor took the precedent of Marquis An Yuan Zheng Ji and enfeoffed them with a thousand households;", idiomatic: "\" The emperor took the precedent of Marquis An Yuan Zheng Ji and enfeoffed them with a thousand households;" },
  { zh: "衡、顯復爭。", literal: "Heng and Xian again contended.", idiomatic: "Heng and Xian again contended." },
  { zh: "夏，四月，戊辰，封延壽為義成侯，賜湯爵關內侯，食邑各三百戶，加賜黃金百斤。", literal: "In summer, the fourth month, on wuchen, Yanshou was enfeoffed as Marquis of Yicheng; Tang was granted the rank of Marquis within the Passes, each with a fief of three hundred households, and in addition a hundred jin of gold was bestowed.", idiomatic: "In summer, the fourth month, on wuchen, Yanshou was enfeoffed as Marquis of Yicheng; Tang was granted the rank of Marquis within the Passes, each with a fief of three hundred households, and in addition a hundred jin of gold was bestowed." },
  { zh: "拜延壽為長水校尉，湯為射聲校尉。", literal: "Yanshou was appointed Colonel of the Long River; Tang was appointed Colonel of the Archers.", idiomatic: "Yanshou was appointed Colonel of the Long River; Tang was appointed Colonel of the Archers." },
  { zh: "於是杜欽上疏追訟馮奉世前破莎車功。", literal: "Thereupon Du Qin submitted a memorial pursuing and claiming Feng Fengshi's earlier achievement in defeating Shache.", idiomatic: "Thereupon Du Qin submitted a memorial pursuing and claiming Feng Fengshi's earlier achievement in defeating Shache." },
  { zh: "上以先帝時事，不復錄。", literal: "The emperor, considering it a matter of the former emperor's time, did not again record it.", idiomatic: "The emperor, considering it a matter of the former emperor's time, did not again record it." },
  { zh: "欽，故御史大夫延年子也。", literal: "Qin was the son of the former Censor-in-Chief Yannian.", idiomatic: "Qin was the son of the former Censor-in-Chief Yannian." },
  { zh: ":荀悅論曰：成其功義足封，追錄前事可也。", literal: ": Xun Yue's discussion says: When achievement is complete and righteousness suffices for enfeoffment, pursuing and recording earlier matters may be allowed.", idiomatic: ": Xun Yue's discussion says: When achievement is complete and righteousness suffices for enfeoffment, pursuing and recording earlier matters may be allowed." },
  { zh: "《春秋》之義，毀泉台則惡之，捨中軍則善之，各由其宜也。", literal: "The meaning of the Spring and Autumn Annals: to destroy the Spring Terrace is condemned; to dismiss the central army is praised—each according to what is fitting.", idiomatic: "The meaning of the Spring and Autumn Annals: to destroy the Spring Terrace is condemned; to dismiss the central army is praised—each according to what is fitting." },
  { zh: "夫矯制之事，先王之所慎也，不得已而行之。", literal: "Now matters of falsifying orders—this the former kings were cautious about; only when unavoidable did they act.", idiomatic: "Matters of falsifying orders—the former kings were cautious about them; only when unavoidable did they act." },
  { zh: "若矯大而功小者，罪之可也；", literal: "If one falsifies greatly yet achievement is small, punishing is permissible;", idiomatic: "If one falsifies greatly yet achievement is small, punishing is permissible;" },
  { zh: "矯小而功大者，賞之可也；", literal: "if one falsifies slightly yet achievement is great, rewarding is permissible;", idiomatic: "if one falsifies slightly yet achievement is great, rewarding is permissible;" },
  { zh: "功過相敵，如斯而已可也。", literal: "if achievement and fault balance each other, to leave it at that alone is permissible.", idiomatic: "if achievement and fault balance each other, to leave it at that alone is permissible." },
  { zh: "權其輕重而為之制宜焉。", literal: "Weigh their lightness and heaviness and make fitting measures for them.", idiomatic: "Weigh their lightness and heaviness and make fitting measures for them." },
  { zh: "----8初，太子少好經書，寬博謹慎；", literal: "----8 Earlier, the heir apparent in youth loved the classics, was broad-minded and cautious;", idiomatic: "----8 Earlier, the heir apparent in youth loved the classics and was broad-minded and cautious;" },
  { zh: "其後幸酒，樂燕樂，上不以為能。", literal: "afterward he favored wine and delighted in banquet music; the emperor did not consider him capable.", idiomatic: "afterward he favored wine and delighted in banquet music; the emperor did not consider him capable." },
  { zh: "而山陽王康有材藝，母傅昭儀又愛幸，上以故常有意欲以山陽王為嗣。", literal: "But the Prince of Shanyang Kang had talent and skill; his mother, Brilliant Companion Fu, was again favored in love, and for this reason the emperor often had the intent to make the Prince of Shanyang heir.", idiomatic: "But the Prince of Shanyang Kang had talent and skill; his mother, Brilliant Companion Fu, was again favored, and for this reason the emperor often intended to make the Prince of Shanyang heir." },
  { zh: "上晚年多疾，不親政事，留好音樂；", literal: "In his later years the emperor had many illnesses, did not personally attend to government, and lingered over music;", idiomatic: "In his later years the emperor had many illnesses, did not personally attend to government, and lingered over music;" },
  { zh: "或置鼙鼓殿下，天子自臨軒檻上，隤銅丸以擿鼓，聲中嚴鼓之節。", literal: "sometimes setting side-drums below the hall; the Son of Heaven himself stood on the balustrade above the steps, rolling copper balls to strike the drums, the sound hitting the beat of the stern drums.", idiomatic: "sometimes setting side-drums below the hall; the emperor himself stood on the balustrade above the steps, rolling copper balls to strike the drums, the sound hitting the beat of the stern drums." },
  { zh: "後宮及左右習知音者莫能為，而山陽王亦能之，上數稱其材。", literal: "Those in the inner palace and attendants versed in knowing pitch could not do it, yet the Prince of Shanyang could also do it; the emperor repeatedly praised his talent.", idiomatic: "Those in the inner palace and attendants versed in pitch could not do it, yet the Prince of Shanyang could; the emperor repeatedly praised his talent." },
  { zh: "史丹進曰：「凡所謂材者，敏而好學，溫故知新，皇太子是也。", literal: "Shi Dan advanced and said: \"What is called talent is quick-wittedness and love of learning, warming the old and knowing the new—the heir apparent is such.", idiomatic: "Shi Dan advanced and said, \"What is called talent is quick-wittedness and love of learning, warming the old and knowing the new—the heir apparent is such." },
  { zh: "若乃器人於絲竹鼓鼙之間，則是陳惠、李微高於匡衡，可相國也！", literal: "If one gauges men amid strings, bamboo, drums, and side-drums, then Chen Hui and Li Wei are higher than Kuang Heng and could be chancellor!", idiomatic: "If one gauges men amid strings, bamboo, drums, and side-drums, then Chen Hui and Li Wei are higher than Kuang Heng and could be chancellor!\"" },
  { zh: "」於是上嘿然而笑。", literal: "\" Thereupon the emperor gave a silent laugh.", idiomatic: "\" Thereupon the emperor gave a silent laugh." },
  { zh: "及上寢疾，傅昭儀、山陽王康常在左右，而皇后、太子希得進見。", literal: "When the emperor lay ill, Brilliant Companion Fu and the Prince of Shanyang Kang were constantly at his side, while the empress and heir apparent seldom obtained audience.", idiomatic: "When the emperor lay ill, Brilliant Companion Fu and the Prince of Shanyang Kang were constantly at his side, while the empress and heir apparent seldom obtained audience." },
  { zh: "上疾稍侵，意忽忽不平，數問尚書以景帝時立膠東王故事。", literal: "As the emperor's illness gradually deepened, his mind was restless and uneasy; he repeatedly questioned the Masters of Writing about the precedent of Emperor Jing's time in establishing the Prince of Jiaodong.", idiomatic: "As the emperor's illness gradually deepened, his mind was restless and uneasy; he repeatedly questioned the Masters of Writing about the precedent of Emperor Jing's time in establishing the Prince of Jiaodong." },
  { zh: "是時太子長舅陽平侯王鳳為衛尉、侍中，與皇后、太子皆憂，不知所出。", literal: "At this time the heir apparent's elder uncle by the maternal line, Wang Feng, Marquis of Yangping, was Commandant of the Guards and Palace Attendant; he, with the empress and heir apparent, were all anxious and knew not what course to take.", idiomatic: "At this time the heir apparent's elder maternal uncle, Wang Feng, Marquis of Yangping, was Commandant of the Guards and Palace Attendant; he, with the empress and heir apparent, were all anxious and knew not what course to take." },
  { zh: "史丹以親密臣得侍視疾，候上間獨寢時，丹直入臥內，頓首伏青蒲上，涕泣而言曰：「皇太子以適長立，積十餘年，名號繫於百姓，天下莫不歸心臣子。", literal: "Shi Dan, as an intimate minister, obtained to attend and view the illness; waiting until the emperor was alone at rest, Dan went straight into the sleeping chamber, knocked his head and lay prostrate on the green rush mat, weeping as he spoke: \"The heir apparent was established as legitimate eldest son, accumulating more than ten years; his title is bound to the common people, and all under Heaven without exception turns its heart to him as subject and son.", idiomatic: "Shi Dan, as an intimate minister, obtained to attend the illness; waiting until the emperor was alone at rest, Dan went straight into the sleeping chamber, knocked his head and lay prostrate on the green rush mat, weeping as he spoke, \"The heir apparent was established as legitimate eldest son for more than ten years; his title is bound to the common people, and all under Heaven turns its heart to him as subject and son." },
  { zh: "見山陽王雅素愛幸，今者道路流言，為國生意，以為太子有動搖之議。", literal: "Seeing the Prince of Shanyang long favored in grace and love, now roadside rumor gives the state unease, thinking there is talk of shaking the heir apparent.", idiomatic: "Seeing the Prince of Shanyang long favored, now roadside rumor gives the state unease, thinking there is talk of displacing the heir apparent." },
  { zh: "審若此，公卿以下必以死爭，不奉詔。", literal: "If it is truly so, from the high ministers down they will surely contend unto death and not obey the edict.", idiomatic: "If it is truly so, from the high ministers down they will surely contend unto death and not obey the edict." },
  { zh: "臣願先賜死以示群臣！", literal: "Your subject wishes to be granted death first to show the assembled ministers!", idiomatic: "Your subject wishes to be granted death first to show the assembled ministers!\"" },
  { zh: "」天子素仁，不忍見丹涕泣，言又切至，意大感寤，喟然太息曰：「吾日困劣，而太子、兩王幼少，意中戀戀，亦何不念乎！", literal: "\" The Son of Heaven was by nature benevolent and could not bear to see Dan weeping; his words were also urgent to the utmost; the emperor was greatly moved to awakening and sighed deeply, saying: \"My days are weary and weak, while the heir apparent and the two kings are young and small—my heart clings to them; how could I not think of them!", idiomatic: "\" The emperor was by nature benevolent and could not bear to see Dan weeping; his words were also urgent to the utmost; the emperor was greatly moved and sighed deeply, saying, \"My days are weary and weak, while the heir apparent and the two kings are young—my heart clings to them; how could I not think of them!" },
  { zh: "然無有此議。", literal: "Yet there is no such deliberation.", idiomatic: "Yet there is no such deliberation." },
  { zh: "且皇后謹慎，先帝又愛太子，吾豈可違指！", literal: "Moreover the empress is cautious; the former emperor also loved the heir apparent—how could I go against his intent!", idiomatic: "Moreover the empress is cautious; the former emperor also loved the heir apparent—how could I go against his intent!" },
  { zh: "駙馬都尉安所受此語？", literal: "Where did the Commandant of Equipage receive this talk?", idiomatic: "Where did the Commandant of Equipage receive this talk?" },
  { zh: "」丹即卻，頓首曰：「愚臣妄聞，罪當死！", literal: "\" Dan thereupon withdrew and knocked his head, saying: \"This foolish minister heard rashly—crime deserves death!", idiomatic: "\" Dan thereupon withdrew and knocked his head, saying, \"This foolish minister heard rashly—crime deserves death!\"" },
  { zh: "」上因納，謂丹曰：「吾病寖加，恐不能自還，善輔道太子，毋違我意。", literal: "\" The emperor thereupon accepted it and said to Dan: \"My illness is gradually increasing; I fear I cannot recover of myself. Well assist and guide the heir apparent—do not go against my intent.", idiomatic: "\" The emperor thereupon accepted it and said to Dan, \"My illness is gradually increasing; I fear I cannot recover. Well assist and guide the heir apparent—do not go against my intent.\"" },
  { zh: "」丹噓唏而起，太子由是遂定為嗣。", literal: "\" Dan sobbed and rose; the heir apparent thereby was settled as successor.", idiomatic: "\" Dan sobbed and rose; the heir apparent thereby was settled as successor." },
  { zh: "而右將軍、光祿大夫王商，中書令石顯亦擁佑太子，頗有力焉。", literal: "Moreover the Right General and Minister of the Household Wang Shang, and Director of the Palace Secretariat Shi Xian, also supported and protected the heir apparent—quite forcefully.", idiomatic: "Moreover the Right General and Minister of the Household Wang Shang, and Director of the Palace Secretariat Shi Xian, also supported and protected the heir apparent—quite forcefully." },
  { zh: "夏，五月，壬辰，帝崩於未央宮。", literal: "In summer, the fifth month, on renchen, the emperor collapsed at Weiyang Palace.", idiomatic: "In summer, the fifth month, on renchen, the emperor collapsed at Weiyang Palace." },
  { zh: ":班彪贊曰：臣外祖兄弟為元帝侍中，語臣曰：「元帝多材藝，善史書，鼓琴瑟，吹洞簫，自度曲，被歌聲，分刌節度，窮極幼眇。", literal: ": Ban Biao's encomium says: My mother's brothers served Emperor Yuan as Palace Attendants and told me: \"Emperor Yuan had many talents and skills, was skilled at historical writing, played qin and se, blew the vertical flute, composed tunes himself, matched them to song, divided and cut rhythmic measures, reaching the utmost subtlety.", idiomatic: ": Ban Biao's encomium says: My mother's brothers served Emperor Yuan as Palace Attendants and told me, \"Emperor Yuan had many talents and skills, was skilled at historical writing, played qin and se, blew the vertical flute, composed tunes himself, matched them to song, divided rhythmic measures, reaching the utmost subtlety." },
  { zh: "少而好儒，及即位，徵用儒生，委之以政，貢、薛、韋、匡迭為宰相。", literal: "In youth he loved Ru learning; upon taking the throne he summoned and employed Ru scholars, entrusting them with government—Gong, Xue, Wei, and Kuang in succession became chancellor.", idiomatic: "In youth he loved Ru learning; upon taking the throne he summoned and employed Ru scholars, entrusting them with government—Gong, Xue, Wei, and Kuang in succession became chancellor." },
  { zh: "而上牽制文義，優遊不斷，孝宣之業衰焉。", literal: "Yet the emperor was constrained by literary nicety, leisurely and undecisive, and the achievement of Emperor Xiaoxuan declined.", idiomatic: "Yet the emperor was constrained by literary nicety, leisurely and undecisive, and the achievement of Emperor Xuan declined." },
  { zh: "然寬弘盡下，出於恭儉，號令溫雅，有古之風烈。", literal: "Yet he was broad and magnanimous in exhausting himself below, proceeding from respect and frugality; his orders were warm and elegant, having the wind and splendor of antiquity.", idiomatic: "Yet he was broad and magnanimous toward those below, proceeding from respect and frugality; his orders were warm and elegant, having the wind and splendor of antiquity.\"" },
  { zh: "」----9匡衡奏言：「前以上體不平，故復諸所罷祠，卒不蒙福。", literal: "\" ----9 Kuang Heng memorialized, saying: \"Previously, because the emperor's person was unwell, the various abolished sacrifices were restored, yet in the end blessings were not received.", idiomatic: "\" ----9 Kuang Heng memorialized, saying, \"Previously, because the emperor's person was unwell, the various abolished sacrifices were restored, yet in the end blessings were not received." },
  { zh: "案-{衛思后}-、戾太子、戾-{后}-園，親未盡。", literal: "Examining -{Empress Weisi}-, the Crown Prince Li, and Empress Li's parks—kinship is not yet exhausted.", idiomatic: "Examining -{Empress Weisi}-, the Crown Prince Li, and Empress Li's parks—kinship is not yet exhausted." },
  { zh: "孝惠、孝景廟，親盡，宜毀。", literal: "The temples of Emperor Xiaohui and Emperor Xiaojing—kinship is exhausted; they ought to be destroyed.", idiomatic: "The temples of Emperor Xiaohui and Emperor Xiaojing—kinship is exhausted; they ought to be destroyed." },
  { zh: "及太上皇、孝文、孝昭太后、昭靈-{后}-、昭哀-{后}-、武哀王祠，請悉罷勿奉。", literal: "As for the Grand Supreme Emperor, Emperor Xiaowen, Empress Dowager Xiaozhao, Empress -{Zhaoling}-, Empress -{Zhaoi}-, and Prince Ai of Wu's sacrifices—your subject requests all be abolished and not offered.", idiomatic: "As for the Grand Supreme Emperor, Emperor Xiaowen, Empress Dowager Xiaozhao, Empress -{Zhaoling}-, Empress -{Zhaoi}-, and Prince Ai of Wu's sacrifices—your subject requests all be abolished and not offered." },
  { zh: "」奏可。", literal: "\" The memorial was approved.", idiomatic: "\" The memorial was approved." },
  { zh: "----10六月，己未，太子即皇帝位，謁高廟。", literal: "----10 In the sixth month, on jiwei, the heir apparent assumed the imperial throne and visited the High Temple.", idiomatic: "----10 In the sixth month, on jiwei, the heir apparent assumed the imperial throne and visited the High Temple." },
  { zh: "尊皇太后曰太皇太后，皇后曰皇太后。", literal: "The empress dowager was honored as Grand Empress Dowager; the empress was honored as Empress Dowager.", idiomatic: "The empress dowager was honored as Grand Empress Dowager; the empress was honored as Empress Dowager." },
  { zh: "以元舅侍中、衛尉、陽平侯王鳳為大司馬、大將軍、領尚書事。", literal: "The emperor's uncle by the maternal line, Palace Attendant and Commandant of the Guards Wang Feng, Marquis of Yangping, was made Grand Marshal, Grand General, and Superintendent of the Masters of Writing.", idiomatic: "The emperor's maternal uncle, Palace Attendant and Commandant of the Guards Wang Feng, Marquis of Yangping, was made Grand Marshal, Grand General, and Superintendent of the Masters of Writing." },
  { zh: "----11秋，七月，丙戌，葬孝元皇帝於渭陵。", literal: "----11 In autumn, the seventh month, on bingxu, Emperor Xiaoyuan was buried at Weiling.", idiomatic: "----11 In autumn, the seventh month, on bingxu, Emperor Yuan was buried at Weiling." },
  { zh: "----12大赦天下。", literal: "----12 A general amnesty was proclaimed for all under Heaven.", idiomatic: "----12 A general amnesty was proclaimed for all under Heaven." },
  { zh: "----13丞相衡上疏曰：「陛下秉至孝，哀傷思慕，不絕於心，未有游虞弋射之宴，誠隆於慎終追遠，無窮已也。", literal: "----13 Chancellor Heng submitted a memorial, saying: \"Your Majesty holds utmost filial piety; grief and longing cease not in the heart; there have been no outings for pleasure, hunting, or archery banquets—truly lofty in careful completion and pursuing the distant, without end.", idiomatic: "----13 Chancellor Heng submitted a memorial, saying, \"Your Majesty holds utmost filial piety; grief and longing cease not in the heart; there have been no outings for pleasure, hunting, or archery banquets—truly lofty in careful completion and pursuing the distant, without end." },
  { zh: "竊願陛下雖聖性得之，猶復加聖心焉！", literal: "Your subject privately wishes that although Your Majesty's sage nature obtains this, you would yet add sage mind to it!", idiomatic: "Your subject privately wishes that although Your Majesty's sage nature obtains this, you would yet add sage mind to it!" },
  { zh: "《詩》云：『煢煢在疚，』言成王喪畢思慕，意氣未能平也。", literal: "The Odes says: 'Alone and grieving in affliction'—it speaks of King Cheng, when mourning was complete, thinking longingly, his spirit not yet able to be calm.", idiomatic: "The Odes says, \"Alone and grieving in affliction\"—it speaks of King Cheng, when mourning was complete, thinking longingly, his spirit not yet able to be calm." },
  { zh: "蓋所以就文、武之業，崇大化之本也。", literal: "This is probably to take up the achievement of Wen and Wu and exalt the root of great transformation.", idiomatic: "This is to take up the achievement of Wen and Wu and exalt the root of great transformation." },
  { zh: "臣又聞之師曰：『妃匹之際，生民之始，萬福之原。", literal: "Your subject also heard from his teacher: 'At the juncture of consort and spouse is the beginning of the living people, the source of ten thousand blessings.", idiomatic: "Your subject also heard from his teacher, \"At the juncture of consort and spouse is the beginning of the living people, the source of ten thousand blessings." },
  { zh: "婚姻之禮正，然後品物遂而天命全。", literal: "When the rites of marriage are correct, then things attain their kinds and Heaven's mandate is complete.", idiomatic: "When the rites of marriage are correct, then things attain their kinds and Heaven's mandate is complete." },
  { zh: "』孔子論《詩》，以《關雎》為始，此綱紀之首，王教之端也。", literal: "' Confucius discussed the Odes, taking Guan Ju as the beginning—this is the head of regulation and the start of royal teaching.", idiomatic: "\" Confucius discussed the Odes, taking Guan Ju as the beginning—this is the head of regulation and the start of royal teaching." },
  { zh: "自上世已來，三代興廢，未有不由此者也。", literal: "From high antiquity onward, the rise and fall of the Three Dynasties—none have not proceeded from this.", idiomatic: "From high antiquity onward, the rise and fall of the Three Dynasties—none have not proceeded from this." },
  { zh: "願陛下詳覽得失盛衰之效，以定大基，采有德，戒聲色，近嚴敬，遠技能。", literal: "Your subject wishes Your Majesty to examine in detail the effects of gain and loss, flourishing and decline, to settle the great foundation, select the virtuous, guard against sound and color, draw near to stern respect, and keep distant from technical skills.", idiomatic: "Your subject wishes Your Majesty to examine in detail the effects of gain and loss, flourishing and decline, to settle the great foundation, select the virtuous, guard against sound and color, draw near to stern respect, and keep distant from technical skills." },
  { zh: "臣聞《六經》者，聖人所以統天地之心，著善惡之歸，明吉凶之分，通人道之正，使不悖於其本性者也。", literal: "Your subject has heard that the Six Classics are what the sage uses to unify the heart of Heaven and Earth, set forth the return of good and evil, clarify the division of fortune and misfortune, penetrate the correctness of the human Way, and cause men not to stray from their native nature.", idiomatic: "Your subject has heard that the Six Classics are what the sage uses to unify the heart of Heaven and Earth, set forth the return of good and evil, clarify the division of fortune and misfortune, penetrate the correctness of the human Way, and cause men not to stray from their native nature." },
  { zh: "及《論語》、《孝經》，聖人言行之要，宜究其意。", literal: "As for the Analects and Classic of Filial Piety—the essentials of the sage's words and conduct—their meaning ought to be thoroughly pursued.", idiomatic: "As for the Analects and Classic of Filial Piety—the essentials of the sage's words and conduct—their meaning ought to be thoroughly pursued." },
  { zh: "臣又聞聖王之自為，動靜周旋，奉天承親，臨朝享臣，物有節文，以章人倫。", literal: "Your subject also heard that the sage king's personal conduct—in movement and stillness, in turning and advancing—serves Heaven and receives kin, faces court and feasts ministers; things have regulated pattern to display human relations.", idiomatic: "Your subject also heard that the sage king's personal conduct—in movement and stillness, in turning and advancing—serves Heaven and receives kin, faces court and feasts ministers; things have regulated pattern to display human relations." },
  { zh: "蓋欽翼祗栗，事天之容也；", literal: "Reverently assisting in awe and fear is the bearing of serving Heaven;", idiomatic: "Reverently assisting in awe and fear is the bearing of serving Heaven;" },
  { zh: "溫恭敬遜，承親之禮也；", literal: "warmth, respect, reverence, and yielding are the rites of receiving kin;", idiomatic: "warmth, respect, reverence, and yielding are the rites of receiving kin;" },
  { zh: "正躬嚴恪，臨眾之儀也；", literal: "correcting the person, stern and strict, is the ceremony of facing the masses;", idiomatic: "correcting the person, stern and strict, is the ceremony of facing the masses;" },
  { zh: "嘉惠和說，饗下之顏也。", literal: "favoring kindness and harmonious pleasure is the countenance of feasting those below.", idiomatic: "favoring kindness and harmonious pleasure is the countenance of feasting those below." },
  { zh: "舉錯動作，物遵其儀，故形為仁義，動為法則。", literal: "In every act and movement, things follow their ceremony; therefore the form becomes benevolence and righteousness, and movement becomes law and standard.", idiomatic: "In every act and movement, things follow their ceremony; therefore the form becomes benevolence and righteousness, and movement becomes law and standard." },
  { zh: "今正月初，幸路寢，臨朝賀，置酒以饗萬方。", literal: "Now at the beginning of the first month, favoring the inner chamber, facing court for congratulations, setting wine to feast the ten thousand regions.", idiomatic: "Now at the beginning of the first month, favoring the inner chamber, facing court for congratulations, setting wine to feast the ten thousand regions." },
  { zh: "《傳》曰：『君子慎始。", literal: "The Commentary says: 'The gentleman is careful at the beginning.", idiomatic: "The Commentary says, \"The gentleman is careful at the beginning." },
  { zh: "』願陛下留神動靜之節，使群下得望盛德休光，以立基楨，天下幸甚！", literal: "' Your subject wishes Your Majesty to keep mind on the measures of movement and stillness, causing the masses below to behold flourishing virtue and beautiful radiance, to establish the foundation and mainstay—all under Heaven would be greatly fortunate!", idiomatic: "\" Your subject wishes Your Majesty to keep mind on the measures of movement and stillness, causing the masses below to behold flourishing virtue and beautiful radiance, to establish the foundation and mainstay—all under Heaven would be greatly fortunate!\"" },
  { zh: "」上敬納其言。", literal: "\" The emperor respectfully accepted his words.", idiomatic: "\" The emperor respectfully accepted his words." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
